cat > /tmp/solve_water.js <<'EOF'
const CAP=4;
const COLORS=4;
function key(tubes){return tubes.map(t=>t.join('')).join('|')}
function isWin(t){return t.every(x=>x.length===0||(x.length===CAP&&x.every(c=>c===x[0])))}
function topGroup(t){if(!t.length)return {c:null,n:0}; const c=t[t.length-1]; let n=1; while(n<t.length&&t[t.length-1-n]===c)n++; return {c,n};}
function moves(tubes){
  // prefer moves that complete tubes / avoid moving whole uniform tube into empty
  const out=[];
  for(let i=0;i<tubes.length;i++){
    if(!tubes[i].length)continue;
    const {c,n}=topGroup(tubes[i]);
    if(n===tubes[i].length && tubes[i].length===CAP) continue; // already done
    for(let j=0;j<tubes.length;j++){
      if(i===j)continue;
      const dest=tubes[j];
      if(dest.length>=CAP)continue;
      if(dest.length&&dest[dest.length-1]!==c)continue;
      if(!dest.length && n===tubes[i].length) continue; // pointless move whole tube to empty
      const amount=Math.min(n,CAP-dest.length);
      const nt=tubes.map(a=>a.slice());
      for(let k=0;k<amount;k++){nt[i].pop();nt[j].push(c);}
      out.push({tubes:nt,i,j,amount});
    }
  }
  return out;
}
function solve(start,limit=2000000){
  const seen=new Set(); let nodes=0; const path=[];
  function dfs(t,depth){
    if(nodes++>limit) return null;
    if(isWin(t)) return [];
    if(depth<=0)return null;
    const k=key(t); if(seen.has(k))return null; seen.add(k);
    let ms=moves(t);
    // move ordering heuristics: completions first, then larger groups
    ms.sort((a,b)=>{
      const compA=a.tubes.filter(x=>x.length===CAP&&x.every(c=>c===x[0])).length;
      const compB=b.tubes.filter(x=>x.length===CAP&&x.every(c=>c===x[0])).length;
      return compB-compA || b.amount-a.amount;
    });
    for(const m of ms){
      const r=dfs(m.tubes,depth-1);
      if(r){return [m,...r];}
    }
    return null;
  }
  for(let d=8;d<=30;d++){
    seen.clear(); nodes=0;
    const r=dfs(start,d);
    if(r) return {solution:r,nodes};
  }
  return null;
}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
// random layouts
for(let iter=0;iter<200;iter++){
  const units=[];
  for(let c=0;c<COLORS;c++)for(let k=0;k<CAP;k++)units.push(c);
  shuffle(units);
  const tubes=[];
  for(let i=0;i<COLORS;i++) tubes.push(units.slice(i*CAP,i*CAP+CAP));
  tubes.push([],[]);
  // skip already solved / too many uniform full
  if(isWin(tubes))continue;
  const res=solve(tubes.map(t=>t.slice()),30);
  if(res && res.solution.length>=10 && res.solution.length<=16){
    console.log('PUZZLE',JSON.stringify(tubes));
    console.log('SOLUTION_LEN',res.solution.length,'nodes',res.nodes);
    console.log('MOVES',res.solution.map(m=>`${m.i}->${m.j}`).join(' '));
    break;
  }
}
EOF
