/* ============================================================
   AdPlay — hyper-casual ad energy, intentionally
   ============================================================ */
:root {
  --ink: #170b26;
  --ink-2: #221033;
  --ink-3: #301747;
  --paper: #fff8ee;
  --muted: #a894c2;
  --yellow: #ffd23f;
  --yellow-deep: #e6a800;
  --pink: #ff5d8c;
  --coral: #ff5d6c;
  --mint: #3ee9a5;
  --blue: #62b6ff;
  --violet: #9b5cff;
  --stroke: rgba(255, 255, 255, 0.11);
  --display: "Arial Rounded MT Bold", "Trebuchet MS", "Avenir Next", system-ui, sans-serif;
  --body: "Avenir Next", "Segoe UI", system-ui, -apple-system, sans-serif;
  --shadow-hard: 0 6px 0 rgba(0, 0, 0, 0.32);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  background: #0d0616;
  color: #fff;
  font-family: var(--body);
  overscroll-behavior: none;
}

body {
  min-height: 100svh;
  display: grid;
  place-items: center;
  overflow: hidden;
  -webkit-tap-highlight-color: transparent;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible {
  outline: 3px solid var(--yellow);
  outline-offset: 3px;
}

svg { display: block; }

/* ---------- ambient desktop set dressing ---------- */
.ambient {
  position: fixed;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  background:
    radial-gradient(circle at 18% 18%, rgba(155, 92, 255, 0.22), transparent 44%),
    radial-gradient(circle at 82% 72%, rgba(255, 93, 140, 0.18), transparent 46%),
    radial-gradient(circle at 55% 115%, rgba(255, 210, 63, 0.1), transparent 48%),
    #0d0616;
}

.ambient::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: radial-gradient(rgba(255, 255, 255, 0.13) 1px, transparent 1.4px);
  background-size: 28px 28px;
  opacity: 0.25;
  mask-image: radial-gradient(circle at center, transparent 38%, #000 100%);
}

.ambient-blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(14px);
  opacity: 0.5;
  animation: drift 18s ease-in-out infinite alternate;
}

.blob-a { width: 380px; height: 380px; left: -120px; top: 8%; background: radial-gradient(circle at 35% 35%, #56258f, transparent 68%); }
.blob-b { width: 440px; height: 440px; right: -140px; bottom: 2%; background: radial-gradient(circle at 60% 40%, #8f1f51, transparent 68%); animation-delay: -7s; }
.blob-c { width: 300px; height: 300px; right: 16%; top: -100px; background: radial-gradient(circle at 50% 50%, #1b6f66, transparent 66%); animation-delay: -12s; }

@keyframes drift {
  from { transform: translate3d(0, 0, 0) scale(1); }
  to { transform: translate3d(24px, -30px, 0) scale(1.08); }
}

.ambient-word {
  position: absolute;
  top: 50%;
  font-family: var(--display);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.34em;
  color: rgba(255, 255, 255, 0.26);
  white-space: nowrap;
}
.word-left { left: 5.5%; transform: translateY(-50%) rotate(-90deg); transform-origin: center; }
.word-right { right: 5.5%; transform: translateY(-50%) rotate(90deg); transform-origin: center; }

@media (max-width: 1040px) {
  .ambient-word { display: none; }
  .ambient-blob { opacity: 0.35; }
}

/* ---------- app frame ---------- */
#app {
  position: relative;
  width: min(100vw, 468px);
  height: 100svh;
  height: 100dvh;
  max-height: 940px;
  overflow: hidden;
  background: var(--ink);
  isolation: isolate;
  padding-top: env(safe-area-inset-top);
  padding-bottom: env(safe-area-inset-bottom);
}

@media (min-width: 720px) and (min-height: 620px) {
  #app {
    height: min(900px, calc(100dvh - 44px));
    border-radius: 34px;
    border: 1px solid rgba(255, 255, 255, 0.14);
    box-shadow:
      0 0 0 7px rgba(255, 255, 255, 0.035),
      0 38px 90px rgba(0, 0, 0, 0.68),
      0 0 70px rgba(155, 92, 255, 0.14);
  }
}

.screen {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.screen[hidden] { display: none !important; }

/* ============================================================
   HOME
   ============================================================ */
.home {
  overflow: hidden;
  background:
    radial-gradient(circle at 82% -8%, rgba(255, 210, 63, 0.16), transparent 34%),
    radial-gradient(circle at 8% 32%, rgba(155, 92, 255, 0.18), transparent 36%),
    linear-gradient(180deg, #1c0c2d 0%, #170b26 45%, #12081e 100%);
}

.home::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(rgba(255, 255, 255, 0.11) 1px, transparent 1.4px);
  background-size: 24px 24px;
  opacity: 0.18;
  mask-image: linear-gradient(180deg, #000, transparent 70%);
}

.home-header {
  position: relative;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px 8px;
  flex: 0 0 auto;
}

.brand {
  display: flex;
  align-items: center;
  gap: 9px;
  user-select: none;
}

.brand-mark {
  width: 30px;
  height: 30px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  color: #170b26;
  background: linear-gradient(150deg, #ffe45e, #ffb703);
  box-shadow: 0 3px 0 #9a6500, 0 6px 18px rgba(255, 183, 3, 0.25);
  transform: rotate(-5deg);
}

.brand-mark svg { width: 20px; height: 20px; margin-left: 1px; }

.brand-word {
  font-family: var(--display);
  font-size: 23px;
  font-weight: 900;
  letter-spacing: -0.055em;
  color: #fff;
}

.brand-word span { color: var(--yellow); }
.brand-dot {
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--mint);
  box-shadow: 0 0 12px rgba(62, 233, 165, 0.9);
  margin-left: -2px;
  align-self: flex-start;
  margin-top: 8px;
}

.header-actions { display: flex; gap: 8px; }

.icon-btn {
  width: 36px;
  height: 36px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--stroke);
  color: #d9c9ee;
  font-weight: 800;
  font-size: 16px;
  transition: transform 0.12s ease, background 0.15s ease;
}

.icon-btn:active { transform: scale(0.92); }
.icon-btn:hover { background: rgba(255, 255, 255, 0.11); }

.sound-btn .sound-off { display: none; }
.sound-btn[aria-pressed="false"] .sound-on { display: none; }
.sound-btn[aria-pressed="false"] .sound-off { display: inline; }

.home-main {
  position: relative;
  z-index: 2;
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 8px 20px 26px;
  scrollbar-width: none;
  overscroll-behavior: contain;
}

.home-main::-webkit-scrollbar { display: none; }

.hero { padding-top: 18px; }

.season-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  background: rgba(255, 255, 255, 0.045);
  color: #cbb8e7;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.live-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--coral);
  box-shadow: 0 0 0 0 rgba(255, 93, 108, 0.55);
  animation: live 1.8s infinite;
}

@keyframes live {
  0% { box-shadow: 0 0 0 0 rgba(255, 93, 108, 0.55); }
  70% { box-shadow: 0 0 0 6px rgba(255, 93, 108, 0); }
  100% { box-shadow: 0 0 0 0 rgba(255, 93, 108, 0); }
}

.hero h1 {
  margin: 15px 0 0;
  font-family: var(--display);
  font-size: clamp(41px, 12.5vw, 54px);
  line-height: 0.88;
  letter-spacing: -0.055em;
  font-weight: 900;
  text-wrap: balance;
}

.hero h1 em {
  font-style: normal;
  color: var(--yellow);
  text-shadow: 0 4px 0 rgba(154, 101, 0, 0.5);
}

.hero h1 .period { color: var(--coral); }

.hero-copy {
  margin: 13px 0 0;
  color: #c8b8dc;
  font-size: 13.2px;
  line-height: 1.5;
  max-width: 330px;
}

.big-play {
  position: relative;
  width: 100%;
  margin-top: 18px;
  padding: 10px 14px 10px 11px;
  border-radius: 18px;
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--ink);
  background: linear-gradient(120deg, #ffe45e 0%, #ffd23f 48%, #ffb703 100%);
  box-shadow: 0 6px 0 #a86f00, 0 15px 34px rgba(255, 183, 3, 0.2);
  transition: transform 0.1s ease, box-shadow 0.1s ease;
  text-align: left;
}

.big-play:active {
  transform: translateY(4px);
  box-shadow: 0 2px 0 #a86f00, 0 8px 18px rgba(255, 183, 3, 0.18);
}

.big-play-icon {
  flex: 0 0 auto;
  width: 42px;
  height: 42px;
  border-radius: 13px;
  background: var(--ink);
  color: var(--yellow);
  display: grid;
  place-items: center;
  box-shadow: inset 0 -3px 0 rgba(0, 0, 0, 0.3);
}

.big-play-icon svg { width: 23px; height: 23px; margin-left: 2px; }
.big-play-text { display: flex; flex-direction: column; min-width: 0; flex: 1; }
.big-play-text small { font-size: 9px; letter-spacing: 0.17em; font-weight: 900; opacity: 0.62; }
.big-play-text strong { font-family: var(--display); font-size: 18px; letter-spacing: -0.02em; font-weight: 900; }
.big-play-arrow { font-size: 24px; font-weight: 900; transition: transform 0.18s ease; }
.big-play:hover .big-play-arrow { transform: translateX(4px); }

.hero-stats {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px 10px;
  margin-top: 14px;
  padding-bottom: 19px;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: #a894c2;
}

.star-total { color: var(--yellow); font-size: 11px; letter-spacing: 0.06em; }
.star-total b { font-size: 13px; }
.star-total .muted { font-size: 10px; }
.muted { color: #8f7ba9; }
.hero-divider { width: 1px; height: 12px; background: rgba(255, 255, 255, 0.14); }
.ad-free-tag {
  margin-left: auto;
  color: #ffb1c1;
  font-size: 8.5px;
  padding: 4px 7px;
  border: 1px solid rgba(255, 93, 140, 0.35);
  border-radius: 6px;
  transform: rotate(-1.5deg);
}

/* level list */
.levels-section { margin-top: 2px; }

.section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 10px;
}

.section-head h2 {
  margin: 0;
  font-family: var(--display);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.19em;
  color: #e5d7f4;
}

.section-note { font-size: 8.5px; font-weight: 800; letter-spacing: 0.16em; color: #7f6b96; }

.level-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
}

.level-card {
  --c1: #ffd23f;
  --c2: #ff5d8c;
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  min-width: 0;
  padding: 10px;
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background:
    linear-gradient(160deg, rgba(255, 255, 255, 0.075), rgba(255, 255, 255, 0.02)),
    rgba(255, 255, 255, 0.02);
  color: #fff;
  text-align: left;
  overflow: hidden;
  transition: transform 0.13s ease, border-color 0.16s ease, background 0.16s ease;
}

.level-card::after {
  content: "";
  position: absolute;
  width: 80px;
  height: 80px;
  right: -28px;
  top: -34px;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, var(--c1) 44%, transparent), transparent 68%);
  pointer-events: none;
}

.level-card:hover {
  border-color: rgba(255, 255, 255, 0.23);
  background:
    linear-gradient(160deg, rgba(255, 255, 255, 0.1), rgba(255, 255, 255, 0.03)),
    rgba(255, 255, 255, 0.03);
}

.level-card:active { transform: scale(0.97); }

.level-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.level-icon {
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  border-radius: 12px;
  display: grid;
  place-items: center;
  font-size: 21px;
  line-height: 1;
  background: linear-gradient(145deg, var(--c1), var(--c2));
  box-shadow: inset 0 -3px 0 rgba(0, 0, 0, 0.18), 0 5px 14px color-mix(in srgb, var(--c2) 30%, transparent);
  filter: saturate(1.1);
}

.level-index {
  font-family: var(--display);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.08em;
  color: rgba(255, 255, 255, 0.42);
  padding-top: 2px;
}

.level-name {
  display: block;
  font-family: var(--display);
  font-size: 13px;
  line-height: 1.05;
  font-weight: 900;
  letter-spacing: -0.015em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.level-studio {
  display: block;
  margin-top: 3px;
  font-size: 8.5px;
  letter-spacing: 0.06em;
  color: #9c88b6;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.level-card-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.stars { display: inline-flex; gap: 1.5px; font-size: 11px; line-height: 1; letter-spacing: 0.03em; color: #4b3b5f; }
.stars .on { color: var(--yellow); text-shadow: 0 0 8px rgba(255, 210, 63, 0.35); }
.level-best { font-size: 8px; letter-spacing: 0.07em; font-weight: 800; color: #8d78a7; white-space: nowrap; }
.level-best b { color: #cbb8e7; }

.level-card.clear { border-color: color-mix(in srgb, var(--c1) 35%, transparent); }

.home-fineprint {
  margin: 17px 2px 4px;
  color: #6f5c86;
  font-size: 9px;
  line-height: 1.5;
  letter-spacing: 0.03em;
  text-align: center;
}

.home-footer {
  position: relative;
  z-index: 2;
  flex: 0 0 auto;
  border-top: 1px solid rgba(255, 255, 255, 0.09);
  background: rgba(9, 4, 16, 0.55);
  overflow: hidden;
}

.ticker { height: 31px; display: flex; align-items: center; overflow: hidden; }
.ticker-track {
  display: inline-flex;
  gap: 26px;
  padding-left: 20px;
  white-space: nowrap;
  color: #9a86b4;
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: 0.13em;
  animation: ticker 32s linear infinite;
}

@keyframes ticker {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}

/* ============================================================
   GAME CHROME
   ============================================================ */
.game { background: #0c0514; }

.adbar {
  flex: 0 0 auto;
  height: 36px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 12px;
  background: #0c0514;
  border-bottom: 1px solid rgba(255, 255, 255, 0.075);
}

.ad-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 18px;
  padding: 0 6px;
  border-radius: 4px;
  background: var(--yellow);
  color: #221100;
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.ad-pulse {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #b16a00;
  animation: live 1.4s infinite;
}

.ad-sponsor { display: flex; flex-direction: column; line-height: 1.05; min-width: 0; flex: 1; }
.ad-sponsor-label { font-size: 6.5px; font-weight: 800; letter-spacing: 0.18em; color: #6e5b86; }
.ad-sponsor strong {
  font-size: 9.5px;
  letter-spacing: 0.02em;
  color: #b7a4cd;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.skip-btn {
  flex: 0 0 auto;
  height: 24px;
  padding: 0 10px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.17);
  color: #ab98c2;
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: 0.1em;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.skip-btn:disabled { opacity: 0.65; cursor: default; }
.skip-btn.ready {
  color: #fff;
  border-color: rgba(255, 255, 255, 0.35);
  background: rgba(255, 255, 255, 0.1);
}
.skip-btn.ready:hover { background: rgba(255, 255, 255, 0.16); }

.game-titlebar {
  flex: 0 0 auto;
  height: 56px;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 0 13px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.075);
  background: linear-gradient(180deg, #140a21, #11071c);
  z-index: 4;
}

.round-btn {
  flex: 0 0 auto;
  width: 34px;
  height: 34px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.065);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #d5c4ea;
  transition: transform 0.12s ease, background 0.15s ease;
}

.round-btn svg { width: 19px; height: 19px; }
.round-btn:active { transform: scale(0.9); }
.round-btn:hover { background: rgba(255, 255, 255, 0.12); }

.game-heading { min-width: 0; flex: 1; }
.game-heading h2 {
  margin: 0;
  font-family: var(--display);
  font-size: 17px;
  line-height: 1.05;
  letter-spacing: -0.025em;
  font-weight: 900;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.game-heading p {
  margin: 2px 0 0;
  font-size: 8.5px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: #8d78a7;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.stage {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
  background: #0b0512;
  touch-action: none;
}

.game-canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
}

.hint-chip {
  position: absolute;
  top: 11px;
  left: 50%;
  transform: translate(-50%, -7px);
  z-index: 6;
  max-width: calc(100% - 26px);
  padding: 7px 12px;
  border-radius: 999px;
  background: rgba(12, 5, 21, 0.82);
  border: 1px solid rgba(255, 255, 255, 0.17);
  color: #f0e7fb;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.035em;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
  backdrop-filter: blur(8px);
}

.hint-chip.show { opacity: 1; transform: translate(-50%, 0); }

.ad-banner {
  flex: 0 0 auto;
  height: 46px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 12px;
  background: linear-gradient(100deg, #ff5d8c, #ff7a4d 55%, #ffd23f);
  color: #2b0b17;
}

.ad-banner-copy { display: flex; align-items: center; gap: 7px; min-width: 0; flex: 1; }
.ad-banner-star { color: #fff8d8; font-size: 9px; letter-spacing: 0.05em; text-shadow: 0 1px 0 rgba(0, 0, 0, 0.18); }
#ad-banner-text {
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: 0.09em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.fake-cta {
  flex: 0 0 auto;
  height: 28px;
  padding: 0 13px;
  border-radius: 8px;
  background: #190a20;
  color: #fff;
  font-family: var(--display);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.06em;
  box-shadow: 0 3px 0 rgba(0, 0, 0, 0.28);
  transition: transform 0.1s ease;
}
.fake-cta:active { transform: translateY(2px); box-shadow: 0 1px 0 rgba(0, 0, 0, 0.28); }

/* ============================================================
   RESULT + OVERLAYS
   ============================================================ */
.result-layer {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 20px;
  background: rgba(8, 3, 14, 0.62);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  animation: fade-in 0.22s ease both;
}

.result-layer[hidden] { display: none !important; }

@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }

.result-card {
  position: relative;
  width: 100%;
  max-width: 340px;
  padding: 24px 20px 18px;
  border-radius: 26px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background:
    radial-gradient(circle at 50% -20%, rgba(255, 210, 63, 0.22), transparent 52%),
    linear-gradient(180deg, #25113b, #170b26 70%);
  box-shadow: 0 26px 70px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.12);
  text-align: center;
  animation: card-pop 0.34s cubic-bezier(0.2, 1.4, 0.4, 1) both;
  overflow: hidden;
}

@keyframes card-pop {
  from { transform: scale(0.88) translateY(12px); opacity: 0; }
  to { transform: scale(1) translateY(0); opacity: 1; }
}

.result-kicker {
  display: inline-block;
  padding: 4px 8px;
  border-radius: 6px;
  background: rgba(255, 210, 63, 0.13);
  border: 1px solid rgba(255, 210, 63, 0.25);
  color: var(--yellow);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.18em;
}

.result-layer.lose .result-kicker {
  color: #ffb1c1;
  background: rgba(255, 93, 108, 0.12);
  border-color: rgba(255, 93, 108, 0.28);
}

.result-title {
  margin: 12px 0 3px;
  font-family: var(--display);
  font-size: 33px;
  line-height: 0.92;
  letter-spacing: -0.045em;
  font-weight: 900;
}

.result-sub {
  margin: 7px 0 0;
  color: #b3a0c9;
  font-size: 11px;
  line-height: 1.45;
}

.result-stars {
  display: flex;
  justify-content: center;
  gap: 5px;
  margin: 17px 0 4px;
  font-size: 38px;
  line-height: 1;
  color: rgba(255, 255, 255, 0.13);
}

.result-stars .on {
  color: var(--yellow);
  text-shadow: 0 0 18px rgba(255, 210, 63, 0.55), 0 3px 0 #9d6b00;
  animation: star-pop 0.45s cubic-bezier(0.2, 1.6, 0.4, 1) both;
}

.result-stars .on:nth-child(2) { animation-delay: 0.1s; }
.result-stars .on:nth-child(3) { animation-delay: 0.2s; }

@keyframes star-pop {
  from { transform: scale(0.3) rotate(-24deg); opacity: 0; }
  to { transform: scale(1) rotate(0); opacity: 1; }
}

.result-score {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin: 8px 0 0;
  color: #d8c8ec;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.result-score .score-val { color: #fff; font-family: var(--display); font-size: 20px; letter-spacing: -0.02em; }
.result-score .score-best { color: #8d78a7; font-weight: 700; letter-spacing: 0.04em; text-transform: none; font-size: 9px; }

.result-note {
  margin: 11px auto 0;
  max-width: 250px;
  padding: 8px 10px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.045);
  border: 1px solid rgba(255, 255, 255, 0.07);
  color: #a894c2;
  font-size: 9.5px;
  line-height: 1.45;
}

.result-actions { display: flex; flex-direction: column; gap: 8px; margin-top: 16px; }

.result-primary {
  height: 46px;
  border-radius: 13px;
  background: linear-gradient(120deg, #ffe45e, #ffd23f 55%, #ffb703);
  color: #221100;
  font-family: var(--display);
  font-size: 14px;
  font-weight: 900;
  letter-spacing: 0.02em;
  box-shadow: 0 5px 0 #9d6b00;
  transition: transform 0.1s ease, box-shadow 0.1s ease;
}
.result-primary:active { transform: translateY(3px); box-shadow: 0 2px 0 #9d6b00; }

.result-primary.ghost {
  background: rgba(255, 255, 255, 0.09);
  color: #fff;
  box-shadow: 0 4px 0 rgba(0, 0, 0, 0.25);
  border: 1px solid rgba(255, 255, 255, 0.14);
}

.result-secondary-row { display: flex; gap: 8px; }
.result-secondary-row button { flex: 1; }

.result-link {
  margin-top: 2px;
  padding: 7px;
  color: #9a86b4;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.result-link:hover { color: #d8c8ec; }

.result-stamp {
  position: absolute;
  top: 13px;
  right: 13px;
  padding: 4px 6px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 5px;
  color: #8d78a7;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: 0.12em;
  transform: rotate(4deg);
}

.confetti { position: absolute; inset: 0; pointer-events: none; overflow: hidden; border-radius: inherit; }
.confetti i {
  position: absolute;
  top: -12px;
  width: 6px;
  height: 11px;
  border-radius: 2px;
  opacity: 0.9;
  animation: confetti-fall var(--dur, 2.1s) cubic-bezier(0.15, 0.7, 0.4, 1) var(--delay, 0s) both;
}

@keyframes confetti-fall {
  from { transform: translateY(-20px) rotate(0deg); }
  to { transform: translateY(430px) rotate(540deg); opacity: 0; }
}

/* help sheet */
.sheet-layer {
  position: absolute;
  inset: 0;
  z-index: 60;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  background: rgba(7, 3, 12, 0.66);
  backdrop-filter: blur(8px);
  animation: fade-in 0.2s ease both;
}

.sheet {
  width: 100%;
  padding: 22px 20px calc(20px + env(safe-area-inset-bottom));
  border-radius: 26px 26px 0 0;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-bottom: 0;
  background: linear-gradient(180deg, #27123e, #170b26 70%);
  box-shadow: 0 -20px 60px rgba(0, 0, 0, 0.5);
  animation: sheet-up 0.3s cubic-bezier(0.2, 1.1, 0.4, 1) both;
}

@keyframes sheet-up {
  from { transform: translateY(40px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

.sheet-grip { width: 36px; height: 4px; border-radius: 99px; background: rgba(255, 255, 255, 0.2); margin: 0 auto 15px; }
.sheet h3 { margin: 0; font-family: var(--display); font-size: 23px; letter-spacing: -0.03em; }
.sheet p { margin: 8px 0 0; color: #b3a0c9; font-size: 11.5px; line-height: 1.5; }
.sheet ul { margin: 13px 0 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 9px; }
.sheet li { display: flex; gap: 9px; color: #d3c3e8; font-size: 10.5px; line-height: 1.4; }
.sheet li b { color: #fff; }
.sheet-num {
  flex: 0 0 auto;
  width: 19px;
  height: 19px;
  border-radius: 6px;
  display: grid;
  place-items: center;
  background: rgba(255, 210, 63, 0.14);
  color: var(--yellow);
  font-size: 9px;
  font-weight: 900;
}
.sheet-close {
  margin-top: 17px;
  width: 100%;
  height: 44px;
  border-radius: 12px;
  background: var(--yellow);
  color: var(--ink);
  font-family: var(--display);
  font-size: 13px;
  font-weight: 900;
  box-shadow: 0 4px 0 #9d6b00;
}
.sheet-close:active { transform: translateY(2px); box-shadow: 0 2px 0 #9d6b00; }

/* toast */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  z-index: 100;
  max-width: min(360px, calc(100vw - 40px));
  padding: 10px 14px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(22, 10, 36, 0.94);
  color: #f1e8fb;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-align: center;
  box-shadow: 0 14px 34px rgba(0, 0, 0, 0.45);
  opacity: 0;
  transform: translate(-50%, 14px);
  pointer-events: none;
  transition: opacity 0.22s ease, transform 0.22s ease;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }

/* shared level overlay pieces */
.mini-hud {
  position: absolute;
  top: 10px;
  left: 10px;
  right: 10px;
  z-index: 5;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  pointer-events: none;
}

.hud-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 9px;
  border-radius: 9px;
  background: rgba(8, 4, 14, 0.62);
  border: 1px solid rgba(255, 255, 255, 0.13);
  color: #eee4fb;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.07em;
  backdrop-filter: blur(5px);
}

.hud-pill .accent { color: var(--yellow); }

.sort-toolbar {
  position: absolute;
  top: 10px;
  left: 10px;
  right: 10px;
  z-index: 6;
  display: flex;
  align-items: center;
  justify-content: space-between;
  pointer-events: none;
}

.sort-toolbar .hud-pill { pointer-events: auto; }

.hud-btn {
  pointer-events: auto;
  height: 29px;
  padding: 0 10px;
  border-radius: 8px;
  background: rgba(8, 4, 14, 0.68);
  border: 1px solid rgba(255, 255, 255, 0.16);
  color: #eee4fb;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.09em;
  backdrop-filter: blur(5px);
}
.hud-btn:disabled { opacity: 0.38; }

.upgrade-layer {
  position: absolute;
  inset: 0;
  z-index: 8;
  display: flex;
  flex-direction: column;
  align-items: center;
