const FILES = {
  runnerA: "./assets/sprites/runner-a.svg",
  runnerB: "./assets/sprites/runner-b.svg",
  runnerC: "./assets/sprites/runner-c.svg",
  ogre: "./assets/sprites/ogre.svg",
  castle: "./assets/sprites/castle.svg",
  coin: "./assets/sprites/coin.svg",
  bomb: "./assets/sprites/bomb.svg",
  knife: "./assets/sprites/knife.svg",
  apple: "./assets/sprites/apple-gold.svg",
  snakeHead: "./assets/sprites/snake-head.svg",
  orbGreen: "./assets/sprites/orb-green.svg",
  orbRed: "./assets/sprites/orb-red.svg",
  dog: "./assets/sprites/dog.svg",
  bee: "./assets/sprites/bee.svg",
  cloud: "./assets/sprites/cloud.svg",
  bush: "./assets/sprites/bush.svg",
  flower: "./assets/sprites/flower.svg",
  survivor: "./assets/sprites/survivor.svg",
  slime: "./assets/sprites/slime.svg",
  gem: "./assets/sprites/gem.svg",
  fighter: "./assets/sprites/fighter.svg",
  eyeBoss: "./assets/sprites/eye-boss.svg",
};

const images = {};
let loaded = false;

export async function loadSprites() {
  if (loaded) return images;
  const entries = Object.entries(FILES);
  await Promise.all(
    entries.map(([key, src]) => new Promise((resolve) => {
      const img = new Image();
      img.decoding = "async";
      img.onload = () => { images[key] = img; resolve(); };
      img.onerror = () => { console.warn(`[adplay] sprite failed to load: ${src}`); resolve(); };
      img.src = src;
    }))
  );
  loaded = true;
  return images;
}

export function sprite(key) {
  return images[key] || null;
}

/**
 * Draw a sprite centered on x,y. Rotation 0 means the sprite's natural
 * orientation (most character sprites face right).
 */
export function drawSprite(ctx, key, x, y, size, opts = {}) {
  const img = images[key];
  if (!img) return false;
  const { rot = 0, alpha = 1, flipX = false, flipY = false, w = size, h = size } = opts;
  ctx.save();
  ctx.translate(x, y);
  if (rot) ctx.rotate(rot);
  if (flipX || flipY) ctx.scale(flipX ? -1 : 1, flipY ? -1 : 1);
  ctx.globalAlpha *= alpha;
  ctx.drawImage(img, -w / 2, -h / 2, w, h);
  ctx.restore();
  return true;
}

export { FILES as SPRITE_FILES };

export const TAU = Math.PI * 2;

export const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const invLerp = (a, b, v) => (v - a) / (b - a);
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a);
export const randInt = (a, b) => Math.floor(rand(a, b + 1));
export const choose = (arr) => arr[Math.floor(Math.random() * arr.length)];
export const chance = (p) => Math.random() < p;
export const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);
export const dist2 = (x1, y1, x2, y2) => (x2 - x1) ** 2 + (y2 - y1) ** 2;

export const easeOutCubic = (t) => 1 - (1 - t) ** 3;
export const easeOutBack = (t) => {
  const c1 = 1.70158;
  const c3 = c1 + 1;
  return 1 + c3 * (t - 1) ** 3 + c1 * (t - 1) ** 2;
};
export const easeInCubic = (t) => t * t * t;

export function normAngle(a) {
  while (a < -Math.PI) a += TAU;
  while (a > Math.PI) a -= TAU;
  return a;
}

export function angleDiff(a, b) {
  return Math.abs(normAngle(a - b));
}

export function rotateToward(current, target, maxStep) {
  const diff = normAngle(target - current);
  if (Math.abs(diff) <= maxStep) return target;
  return current + Math.sign(diff) * maxStep;
}

export function formatTime(seconds) {
  const s = Math.max(0, Math.ceil(seconds));
  return `${s}s`;
}

export function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(typeof r === "number" ? r : 0, Math.abs(w) / 2, Math.abs(h) / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

export function starPath(ctx, cx, cy, outer, inner, points = 5, rotation = -Math.PI / 2) {
  ctx.beginPath();
  for (let i = 0; i < points * 2; i++) {
    const r = i % 2 === 0 ? outer : inner;
    const a = rotation + (i * Math.PI) / points;
    const x = cx + Math.cos(a) * r;
    const y = cy + Math.sin(a) * r;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
}

/**
 * Size a canvas to its container, handling DPR and resize.
 */
export function createStage(container) {
  const canvas = document.createElement("canvas");
  canvas.className = "game-canvas";
  container.appendChild(canvas);
  const ctx = canvas.getContext("2d", { alpha: false });
  let w = 320;
  let h = 480;
  let dpr = 1;
  const listeners = new Set();

  function resize() {
    const rect = container.getBoundingClientRect();
    const nextW = Math.max(220, Math.round(rect.width || 320));
    const nextH = Math.max(280, Math.round(rect.height || 480));
    dpr = Math.min(2, window.devicePixelRatio || 1);
    w = nextW;
    h = nextH;
    canvas.width = Math.round(w * dpr);
    canvas.height = Math.round(h * dpr);
    canvas.style.width = `${w}px`;
    canvas.style.height = `${h}px`;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    listeners.forEach((fn) => fn(w, h));
  }

  let frame = 0;
  const ro = typeof ResizeObserver !== "undefined" ? new ResizeObserver(resize) : null;
  ro?.observe(container);
  window.addEventListener("resize", resize);
  frame = requestAnimationFrame(resize);
  resize();

  return {
    canvas,
    ctx,
    get w() { return w; },
    get h() { return h; },
    onResize(fn) {
      listeners.add(fn);
      return () => listeners.delete(fn);
    },
    destroy() {
      cancelAnimationFrame(frame);
      ro?.disconnect();
      window.removeEventListener("resize", resize);
      listeners.clear();
      canvas.remove();
    },
  };
}

export function createLoop(update) {
  let raf = 0;
  let last = 0;
  let running = true;
  let paused = false;

  function tick(now) {
    if (!running) return;
    if (!last) last = now;
    const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
    last = now;
    if (!paused) update(dt);
    raf = requestAnimationFrame(tick);
  }

  raf = requestAnimationFrame(tick);

  return {
    stop() {
      running = false;
      cancelAnimationFrame(raf);
    },
    pause() { paused = true; last = 0; },
    resume() { paused = false; last = 0; },
    get paused() { return paused; },
  };
}

export function pointOnCanvas(canvas, event) {
  const rect = canvas.getBoundingClientRect();
  return {
    x: ((event.clientX - rect.left) / rect.width) * canvas.clientWidth,
    y: ((event.clientY - rect.top) / rect.height) * canvas.clientHeight,
  };
}

export function bindPointer(canvas, handlers = {}) {
  const local = (e) => pointOnCanvas(canvas, e);
  let dragging = false;

  const down = (e) => {
    if (e.pointerType === "mouse" && e.button !== 0) return;
    e.preventDefault();
    dragging = true;
    try { canvas.setPointerCapture(e.pointerId); } catch {}
    handlers.down?.(local(e), e);
  };
  const move = (e) => {
    const p = local(e);
    if (dragging || e.pointerType === "mouse") handlers.move?.(p, e);
  };
  const up = (e) => {
    if (!dragging) return;
    dragging = false;
    try { canvas.releasePointerCapture(e.pointerId); } catch {}
    handlers.up?.(local(e), e);
  };
  const leave = (e) => {
    handlers.leave?.(local(e), e);
  };
  const cancel = (e) => {
    if (!dragging) return;
    dragging = false;
    handlers.up?.(local(e), e);
  };

  canvas.addEventListener("pointerdown", down);
  canvas.addEventListener("pointermove", move);
  canvas.addEventListener("pointerup", up);
  canvas.addEventListener("pointercancel", cancel);
  canvas.addEventListener("pointerleave", leave);
  canvas.addEventListener("contextmenu", (e) => e.preventDefault());

  return () => {
    canvas.removeEventListener("pointerdown", down);
    canvas.removeEventListener("pointermove", move);
    canvas.removeEventListener("pointerup", up);
    canvas.removeEventListener("pointercancel", cancel);
    canvas.removeEventListener("pointerleave", leave);
  };
}

export function createKeyboard() {
  const down = new Set();
  const pressed = new Set();
  const prevent = new Set([
    "arrowleft", "arrowright", "arrowup", "arrowdown", " ", "spacebar",
  ]);

  const onDown = (e) => {
    const k = e.key.toLowerCase();
    if (prevent.has(k)) e.preventDefault();
    if (!down.has(k)) pressed.add(k);
    down.add(k);
  };
  const onUp = (e) => {
    down.delete(e.key.toLowerCase());
  };
  const onBlur = () => { down.clear(); pressed.clear(); };

  window.addEventListener("keydown", onDown, { passive: false });
  window.addEventListener("keyup", onUp);
  window.addEventListener("blur", onBlur);

  return {
    isDown(...keys) { return keys.some((k) => down.has(k)); },
    wasPressed(...keys) { return keys.some((k) => pressed.has(k)); },
    endFrame() { pressed.clear(); },
    destroy() {
      window.removeEventListener("keydown", onDown);
      window.removeEventListener("keyup", onUp);
      window.removeEventListener("blur", onBlur);
    },
  };
}

export function shakeOffset(intensity, time, seed = 0) {
  return {
    x: Math.sin(time * 71 + seed) * intensity,
    y: Math.cos(time * 83 + seed * 2) * intensity,
  };
}

export function drawStars(ctx, count, total, x, y, size, gap) {
  for (let i = 0; i < total; i++) {
    ctx.save();
    ctx.translate(x + i * (size + gap), y);
    starPath(ctx, 0, 0, size / 2, size / 4.2);
    ctx.fillStyle = i < count ? "#ffd23f" : "rgba(255,255,255,0.16)";
    ctx.fill();
    ctx.restore();
  }
}

/**
 * Tiny WebAudio synth. No audio files, no autoplay issues:
 * the context is created/resumed from a user gesture.
 */
class AudioKit {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.enabled = true;
    this.noiseBuffer = null;
  }

  ensure() {
    if (!this.enabled) return null;
    if (!this.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.42;
      const comp = this.ctx.createDynamicsCompressor();
      comp.threshold.value = -18;
      comp.knee.value = 18;
      comp.ratio.value = 5;
      this.master.connect(comp);
      comp.connect(this.ctx.destination);
    }
    if (this.ctx.state === "suspended") this.ctx.resume().catch(() => {});
    return this.ctx;
  }

  setEnabled(value) {
    this.enabled = value;
    if (value) this.ensure();
  }

  get now() { return this.ctx ? this.ctx.currentTime : 0; }

  tone(freq, dur = 0.12, opts = {}) {
    const ctx = this.ensure();
    if (!ctx) return;
    const {
      type = "sine", vol = 0.16, delay = 0, slide = null, attack = 0.008,
    } = opts;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, freq), t0);
    if (slide != null) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slide), t0 + dur);
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t0 + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.03);
  }

  noise(dur = 0.2, opts = {}) {
    const ctx = this.ensure();
    if (!ctx) return;
    const { vol = 0.12, delay = 0, freq = 900, q = 0.8, type = "bandpass", slide = null } = opts;
    if (!this.noiseBuffer) {
      const len = Math.floor(ctx.sampleRate * 1.2);
      const buf = ctx.createBuffer(1, len, ctx.sampleRate);
      const data = buf.getChannelData(0);
      for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
      this.noiseBuffer = buf;
    }
    const t0 = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, t0);
    filter.Q.value = q;
    if (slide != null) filter.frequency.exponentialRampToValueAtTime(Math.max(40, slide), t0 + dur);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t0 + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    src.start(t0);
    src.stop(t0 + dur + 0.02);
  }

  tap() { this.tone(520, 0.05, { type: "triangle", vol: 0.1, slide: 760 }); }
  click() { this.tone(340, 0.045, { type: "square", vol: 0.05, slide: 420 }); }
  pop() { this.tone(560, 0.09, { type: "sine", vol: 0.16, slide: 980 }); }
  eat() { this.tone(440, 0.07, { type: "triangle", vol: 0.14, slide: 880 }); this.tone(880, 0.06, { type: "sine", vol: 0.07, delay: 0.04, slide: 1180 }); }
  good() { this.tone(660, 0.09, { type: "triangle", vol: 0.15 }); this.tone(990, 0.13, { type: "triangle", vol: 0.13, delay: 0.07 }); }
  bad() { this.tone(190, 0.28, { type: "sawtooth", vol: 0.14, slide: 55 }); this.noise(0.22, { vol: 0.1, freq: 400, slide: 120 }); }
  fail() { this.tone(240, 0.2, { type: "square", vol: 0.08, slide: 90 }); this.tone(180, 0.34, { type: "sawtooth", vol: 0.09, delay: 0.1, slide: 50 }); }
  thunk() { this.tone(150, 0.09, { type: "triangle", vol: 0.22, slide: 60 }); this.noise(0.06, { vol: 0.13, freq: 240, q: 1.2 }); }
  whoosh() { this.noise(0.14, { vol: 0.11, freq: 500, slide: 2200, q: 1.1 }); }
  tick() { this.tone(900, 0.032, { type: "square", vol: 0.05 }); }
  graze() { this.tone(1420, 0.045, { type: "sine", vol: 0.055, slide: 1860 }); }
  shoot() { this.tone(760, 0.055, { type: "square", vol: 0.055, slide: 260 }); }
  hurt() { this.tone(220, 0.16, { type: "sawtooth", vol: 0.16, slide: 90 }); this.noise(0.12, { vol: 0.1, freq: 300 }); }
  splash() { this.noise(0.2, { vol: 0.12, freq: 1400, slide: 300, q: 0.7 }); }
  levelUp() {
    [523, 659, 784, 1047].forEach((f, i) => this.tone(f, 0.18, { type: "triangle", vol: 0.13, delay: i * 0.07 }));
  }
  win() {
    [523, 659, 784, 1047, 1319].forEach((f, i) => this.tone(f, 0.26, { type: "triangle", vol: 0.15, delay: i * 0.085 }));
    this.tone(1568, 0.5, { type: "sine", vol: 0.1, delay: 0.45 });
  }
  lose() {
    [392, 330, 262, 196].forEach((f, i) => this.tone(f, 0.22, { type: "sawtooth", vol: 0.09, delay: i * 0.12 }));
  }
}

export const audio = new AudioKit();

