import {
  createStage, bindPointer, createKeyboard, createLoop,
  clamp, lerp, rand, roundRect, TAU, easeOutCubic, drawStars,
} from "../util.js";
import { drawSprite } from "../sprites.js";
import { audio } from "../audio.js";

const DISPLAY = '"Arial Rounded MT Bold", "Trebuchet MS", system-ui, sans-serif';

const GATE_DEFS = [
  [{ kind: "mul", value: 2, label: "×2" }, { kind: "add", value: 4, label: "+4" }],
  [{ kind: "add", value: 28, label: "+28" }, { kind: "add", value: 6, label: "+6" }],
  [{ kind: "mul", value: 2, label: "×2" }, { kind: "add", value: 9, label: "+9" }],
  [{ kind: "mul", value: 3, label: "×3" }, { kind: "add", value: 12, label: "+12" }],
  [{ kind: "add", value: 32, label: "+32" }, { kind: "add", value: 10, label: "+10" }],
  [{ kind: "mul", value: 2, label: "×2" }, { kind: "add", value: 18, label: "+18" }],
];
const GATE_AT = [0.62, 1.5, 2.4, 3.3, 4.2, 5.1];
const FINISH = 5.85;
const BOSS_HP = 80;

export function mount(root, api) {
  root.innerHTML = "";
  const stage = createStage(root);
  const input = createKeyboard();

  const state = {
    phase: "run",
    progress: 0,
    speed: 0.445,
    count: 8,
    x: 0.5,
    targetX: 0.5,
    time: 0,
    battleT: 0,
    finished: false,
    shake: 0,
    flash: 0,
    gates: GATE_DEFS.map((ops, i) => {
      const pair = Math.random() < 0.5 ? ops : [ops[1], ops[0]];
      return { at: GATE_AT[i], ops: pair, hit: false, chosen: -1, flash: 0 };
    }),
    pickups: [],
    floats: [],
    particles: [],
    crowd: createCrowd(),
    indicator: 0,
  };

  buildPickups(state.pickups);

  function createCrowd() {
    const members = [];
    for (let i = 0; i < 34; i++) {
      const ring = Math.floor(Math.sqrt(i));
      const a = i * 2.399;
      const r = 2.2 + ring * 1.35;
      members.push({
        ox: Math.cos(a) * r,
        oy: Math.sin(a) * r * 0.7,
        phase: Math.random() * TAU,
        look: i % 3,
      });
    }
    return members;
  }

  function buildPickups() {
    const types = [
      { type: "coin", weight: 0.38, value: 6 },
      { type: "ally", weight: 0.34, value: 4 },
      { type: "bomb", weight: 0.28, value: -7 },
    ];
    const spawn = (d) => {
      let roll = Math.random();
      let picked = types[0];
      for (const t of types) {
        if (roll < t.weight) { picked = t; break; }
        roll -= t.weight;
      }
      return {
        at: d,
        x: rand(0.16, 0.84),
        type: picked.type,
        value: picked.value,
        hit: false,
        bob: Math.random() * TAU,
      };
    };
    state.pickups.push(spawn(0.34));
    for (let i = 0; i < GATE_AT.length; i++) {
      const start = GATE_AT[i] + 0.12;
      const end = i < GATE_AT.length - 1 ? GATE_AT[i + 1] - 0.1 : FINISH - 0.24;
      state.pickups.push(spawn(rand(start, Math.max(start + 0.05, end))));
      if (i % 2 === 0) state.pickups.push(spawn(rand(start, Math.max(start + 0.05, end))));
    }
  }

  let pointerActive = false;
  const stopPointer = bindPointer(stage.canvas, {
    down(p) {
      pointerActive = true;
      state.targetX = clamp(p.x / stage.w, 0.12, 0.88);
    },
    move(p, e) {
      if (pointerActive || e.pointerType === "mouse") {
        state.targetX = clamp(p.x / stage.w, 0.12, 0.88);
      }
    },
    up() { pointerActive = false; },
    leave() { pointerActive = false; },
  });

  function addFloat(text, color, x, y, size = 1) {
    state.floats.push({ text, color, x, y, life: 1.15, max: 1.15, size });
  }

  function burst(x, y, color, amount = 10, power = 180) {
    for (let i = 0; i < amount; i++) {
      const a = rand(0, TAU);
      const s = rand(power * 0.3, power);
      state.particles.push({
        x, y,
        vx: Math.cos(a) * s,
        vy: Math.sin(a) * s - 40,
        life: rand(0.35, 0.75),
        max: 0.75,
        size: rand(2, 5),
        color,
      });
    }
  }

  function applyOp(gate, side) {
    const op = gate.ops[side];
    const before = state.count;
    if (op.kind === "mul") state.count = Math.max(0, Math.round(state.count * op.value));
    else state.count = Math.max(0, state.count + op.value);
    const gained = state.count - before;
    const good = gained >= 0;
    addFloat(`${op.label}  ${gained >= 0 ? "+" : ""}${gained}`, good ? "#2ee6a6" : "#ff5d6c", state.x * stage.w, stage.h * 0.55, 1.25);
    burst(state.x * stage.w, stage.h * 0.68, good ? "#ffd23f" : "#ff5d6c", 14, 210);
    gate.flash = 0.5;
    state.flash = 0.18;
    if (op.kind === "mul") audio.good(); else audio.pop();
    if (state.count <= 0 && !state.finished) {
      state.finished = true;
      state.phase = "dead";
      setTimeout(() => api.lose("Your whole squad got wiped before the boss."), 650);
    }
    api.vibrate?.(10);
  }

  function update(dt) {
    state.time += dt;
    input.endFrame();
    if (state.phase === "run") {
      // steering
      let steer = 0;
      if (input.isDown("arrowleft", "a")) steer -= 1;
      if (input.isDown("arrowright", "d")) steer += 1;
      if (steer) state.targetX = clamp(state.targetX + steer * 1.35 * dt, 0.12, 0.88);
      state.targetX = clamp(state.targetX, 0.12, 0.88);
      state.x = lerp(state.x, state.targetX, 1 - Math.exp(-11 * dt));

      state.progress += state.speed * dt;

      for (const gate of state.gates) {
        if (!gate.hit && state.progress >= gate.at) {
          gate.hit = true;
          const side = state.x < 0.5 ? 0 : 1;
          gate.chosen = side;
          applyOp(gate, side);
        }
        gate.flash = Math.max(0, gate.flash - dt);
      }

      for (const p of state.pickups) {
        if (!p.hit && state.progress >= p.at) {
          p.hit = true;
          if (Math.abs(state.x - p.x) < 0.095) {
            state.count = Math.max(0, state.count + p.value);
            const color = p.value > 0 ? "#ffd23f" : "#ff5d6c";
            addFloat(`${p.value > 0 ? "+" : ""}${p.value}`, color, p.x * stage.w, stage.h * 0.66, 1.1);
            burst(p.x * stage.w, stage.h * 0.69, color, p.value > 0 ? 9 : 14, 160);
            if (p.value > 0) audio.eat(); else audio.bad();
          }
        }
      }

      if (state.progress >= FINISH && state.phase === "run") {
        state.phase = "battle";
        state.battleT = 0;
        state.shake = 6;
        audio.bad();
        api.vibrate?.(35);
      }
    } else if (state.phase === "battle") {
      state.battleT += dt;
      state.shake = Math.max(0, state.shake - dt * 12);
      if (!state.finished && state.battleT > 1.5) {
        state.finished = true;
        state.phase = state.count >= BOSS_HP ? "won" : "lost";
        if (state.count >= BOSS_HP) {
          const stars = state.count >= 260 ? 3 : state.count >= 130 ? 2 : 1;
          api.win(stars, state.count, {
            note: state.count >= 260
              ? "The boss never stood a chance. Neither did your thumbs."
              : "Boss defeated. The ad would like you to install anyway.",
          });
        } else {
          api.lose(`You reached the boss with ${state.count}. You needed ${BOSS_HP}.`);
        }
      }
    }

    state.flash = Math.max(0, state.flash - dt * 2.4);
    state.indicator += dt;

    for (const f of state.floats) {
      f.life -= dt;
      f.y -= 42 * dt;
    }
    state.floats = state.floats.filter((f) => f.life > 0);

    for (const p of state.particles) {
      p.life -= dt;
      p.vy += 360 * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vx *= 1 - dt * 1.4;
    }
    state.particles = state.particles.filter((p) => p.life > 0);
  }

  function drawBackdrop(ctx, w, h) {
    const sky = ctx.createLinearGradient(0, 0, 0, h);
    sky.addColorStop(0, "#5ed5ff");
    sky.addColorStop(0.42, "#b9ecff");
    sky.addColorStop(0.72, "#ffe0ef");
    sky.addColorStop(1, "#ffc6dc");
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, w, h);

    // sun
    ctx.save();
    ctx.globalAlpha = 0.6;
    ctx.fillStyle = "#fff5b8";
    ctx.beginPath();
    ctx.arc(w * 0.78, h * 0.12, w * 0.13, 0, TAU);
    ctx.fill();
    ctx.restore();

    // parallax hills
    const scroll = state.progress * h;
    for (let layer = 0; layer < 2; layer++) {
      const baseY = h * (0.22 + layer * 0.08);
      const amp = h * (0.035 + layer * 0.012);
      ctx.fillStyle = layer === 0 ? "rgba(112, 220, 172, 0.55)" : "rgba(61, 195, 137, 0.45)";
      ctx.beginPath();
      ctx.moveTo(0, h);
      for (let x = 0; x <= w; x += 18) {
        const y = baseY + Math.sin((x + scroll * (0.18 + layer * 0.15)) * 0.018 + layer) * amp;
        ctx.lineTo(x, y);
      }
      ctx.lineTo(w, h);
      ctx.closePath();
      ctx.fill();
    }

    // clouds
    const cloudSprites = ["cloud"];
    for (let i = 0; i < 4; i++) {
      const cx = ((i * 173 - scroll * (0.06 + i * 0.014)) % (w + 180)) - 90;
      const cy = h * (0.06 + i * 0.06);
      drawSprite(ctx, cloudSprites[0], ((cx % (w + 180)) + (w + 180)) % (w + 180) - 90, cy, w * (0.22 + i * 0.025), { alpha: 0.55 + i * 0.08 });
    }

    // track
    const left = w * 0.085;
    const right = w * 0.915;
    ctx.save();
    ctx.fillStyle = "#ffe9c7";
    roundRect(ctx, left - 8, 0, right - left + 16, h, 0);
    ctx.fill();
    const road = ctx.createLinearGradient(left, 0, right, 0);
    road.addColorStop(0, "#ffd6ae");
    road.addColorStop(0.5, "#ffe6c6");
    road.addColorStop(1, "#ffd0a6");
    ctx.fillStyle = road;
    roundRect(ctx, left, 0, right - left, h, 0);
    ctx.fill();

    // scrolling rungs
    ctx.strokeStyle = "rgba(196, 106, 125, 0.16)";
    ctx.lineWidth = 2;
    for (let d = -1; d < state.progress + 1.4; d += 0.16) {
      const y = h * 0.72 + (state.progress - d) * h;
      if (y < -20 || y > h + 20) continue;
      ctx.beginPath();
      ctx.moveTo(left + 12, y);
      ctx.lineTo(right - 12, y);
      ctx.stroke();
    }

    // center dashes
    ctx.setLineDash([14, 18]);
    ctx.lineDashOffset = (scroll % 32);
    ctx.strokeStyle = "rgba(255, 255, 255, 0.72)";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(w / 2, 0);
    ctx.lineTo(w / 2, h);
    ctx.stroke();
    ctx.setLineDash([]);

    // fences
    for (const x of [left - 4, right + 4]) {
      ctx.fillStyle = "#b96b7e";
      ctx.fillRect(x - 2, 0, 4, h);
      for (let d = -1; d < state.progress + 1.4; d += 0.08) {
        const y = h * 0.72 + (state.progress - d) * h;
        if (y < -10 || y > h + 10) continue;
        ctx.fillStyle = "#ff9ab7";
        ctx.beginPath();
        ctx.arc(x, y, 3.4, 0, TAU);
        ctx.fill();
      }
    }

    // side vegetation
    for (let i = 0; i < 6; i++) {
      const d = -0.4 + i * 1.05;
      const y = h * 0.72 + (state.progress - d) * h;
      drawSprite(ctx, i % 2 ? "bush" : "flower", i % 2 ? w * 0.045 : w * 0.95, ((y % (h * 1.8)) + h * 1.8) % (h * 1.8) - h * 0.4, i % 2 ? w * 0.15 : w * 0.09, { alpha: 0.9 });
    }
    ctx.restore();
  }

  function gateScreenY(gate, h) {
    return h * 0.72 + (state.progress - gate.at) * h;
  }

  function drawGate(ctx, gate, w, h, index) {
    const y = gateScreenY(gate, h);
    const gateH = Math.min(h * 0.16, 120);
    if (y < -gateH || y > h + gateH) return;
    const left = w * 0.085;
    const right = w * 0.915;
    const mid = w / 2;
    const pad = 4;
    const chosenWorld = state.x < 0.5 ? 0 : 1;

    for (let side = 0; side < 2; side++) {
      const x = side === 0 ? left : mid;
      const pw = mid - left - pad;
      const op = gate.ops[side];
      const isChosen = gate.hit && gate.chosen === side;
      const active = !gate.hit && side === chosenWorld;
      const strong = op.kind === "mul" || (op.kind === "add" && op.value >= 20);
      const base = strong ? "#2ee6a6" : "#ffd23f";
      const alpha = gate.hit ? (isChosen ? 0.34 : 0.1) : active ? 0.34 : 0.22;
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.fillStyle = base;
      roundRect(ctx, x + pad, y - gateH / 2, pw - pad * 2, gateH, 14);
      ctx.fill();
      ctx.globalAlpha = gate.hit ? (isChosen ? 1 : 0.35) : active ? 1 : 0.65;
      ctx.strokeStyle = strong ? "#0d8f63" : "#b07b00";
      ctx.lineWidth = active ? 4 : 3;
      roundRect(ctx, x + pad, y - gateH / 2, pw - pad * 2, gateH, 14);
      ctx.stroke();
      ctx.globalAlpha = gate.hit ? (isChosen ? 1 : 0.25) : 1;
      ctx.fillStyle = "#20142e";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.font = `900 ${Math.round(clamp(w * 0.09, 22, 40))}px ${DISPLAY}`;
      ctx.fillText(op.label, x + pw / 2, y + 2);
      if (strong && !gate.hit) {
        ctx.font = `900 ${Math.round(clamp(w * 0.022, 8, 11))}px ${DISPLAY}`;
        ctx.fillStyle = "rgba(20, 12, 30, 0.62)";
        ctx.fillText(op.kind === "mul" ? "MULTIPLY" : "BIG GAIN", x + pw / 2, y + gateH * 0.3);
      }
      if (gate.hit && isChosen) {
        ctx.fillStyle = "#20142e";
        ctx.font = `900 ${Math.round(clamp(w * 0.022, 8, 11))}px ${DISPLAY}`;
        ctx.fillText("CHOSEN", x + pw / 2, y + gateH * 0.3);
      }
      ctx.restore();
    }

    // gate posts
    ctx.save();
    ctx.fillStyle = "#a05d75";
    ctx.globalAlpha = 0.55;
    ctx.fillRect(left - 7, y - gateH * 0.58, 5, gateH * 1.16);
    ctx.fillRect(right + 2, y - gateH * 0.58, 5, gateH * 1.16);
    ctx.restore();
  }

  function drawPickup(ctx, p, w, h) {
    const y = gateScreenY(p, h);
    const x = p.x * w;
    if (y < -40 || y > h + 40) return;
    const bob = Math.sin(state.time * 5 + p.bob) * 3;
    ctx.save();
    ctx.globalAlpha = p.hit ? 0.18 : 1;
    if (p.type === "coin") {
      drawSprite(ctx, "coin", x, y + bob, clamp(w * 0.085, 24, 36), { rot: Math.sin(state.time * 2 + p.bob) * 0.18 });
      ctx.fillStyle = "#7a4100";
      ctx.font = `900 ${Math.round(clamp(w * 0.027, 10, 13))}px ${DISPLAY}`;
      ctx.textAlign = "center";
      ctx.fillText("+6", x, y + 27);
    } else if (p.type === "bomb") {
      drawSprite(ctx, "bomb", x, y + bob, clamp(w * 0.09, 26, 38));
      ctx.fillStyle = "#8b1e34";
      ctx.font = `900 ${Math.round(clamp(w * 0.027, 10, 13))}px ${DISPLAY}`;
      ctx.textAlign = "center";
      ctx.fillText("-7", x, y + 28);
    } else {
      drawSprite(ctx, "runnerB", x, y + bob, clamp(w * 0.08, 24, 34));
      ctx.strokeStyle = "rgba(255,255,255,0.9)";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(x, y + bob, clamp(w * 0.055, 17, 24), 0, TAU);
      ctx.stroke();
      ctx.fillStyle = "#0c6c48";
      ctx.font = `900 ${Math.round(clamp(w * 0.026, 9, 12))}px ${DISPLAY}`;
      ctx.textAlign = "center";
      ctx.fillText("+4", x, y + 27);
    }
    ctx.restore();
  }

  function drawCrowd(ctx, w, h) {
    const playerY = h * 0.72;
    let px = state.x * w;
    let py = playerY;
    if (state.phase === "battle") {
      const t = Math.min(1, state.battleT / 1.2);
      py -= easeOutCubic(t) * h * 0.16;
    }
    if (state.phase === "won") py -= h * 0.16;

    // shadow + formation
    ctx.save();
    ctx.fillStyle = "rgba(72, 31, 62, 0.22)";
    ctx.beginPath();
    ctx.ellipse(px, playerY + 17, Math.min(w * 0.16, 62), 12, 0, 0, TAU);
    ctx.fill();

    const visual = clamp(Math.ceil(state.count / 3) + 2, 3, state.crowd.length);
    const members = state.crowd.slice(0, visual);
    const scale = clamp(w * 0.082, 25, 40);
    const spread = clamp(0.6 + Math.sqrt(state.count) * 0.09, 0.8, 2.1);
    const bob = Math.sin(state.time * 11) * 2;
    const sorted = [...members].sort((a, b) => a.oy - b.oy);
    for (const m of sorted) {
      const wobble = Math.sin(state.time * 10 + m.phase) * 2;
      const mx = px + m.ox * scale * spread * 0.34;
      const my = py + m.oy * scale * spread * 0.3 + wobble + bob;
      const look = m.look === 0 ? "runnerA" : m.look === 1 ? "runnerB" : "runnerC";
      ctx.globalAlpha = 0.95;
      drawSprite(ctx, look, mx, my, scale);
    }
    ctx.restore();

    // count badge
    const badgeW = clamp(w * 0.2, 74, 100);
    const badgeH = clamp(h * 0.042, 27, 34);
    ctx.save();
    ctx.shadowColor = "rgba(0,0,0,0.28)";
    ctx.shadowBlur = 10;
    ctx.shadowOffsetY = 3;
    ctx.fillStyle = "#20142e";
    roundRect(ctx, px - badgeW / 2, py - scale * 1.5 - 12, badgeW, badgeH, badgeH / 2);
    ctx.fill();
    ctx.shadowColor = "transparent";
    ctx.fillStyle = "#ffd23f";
    ctx.font = `900 ${Math.round(badgeH * 0.58)}px ${DISPLAY}`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(`× ${state.count}`, px, py - scale * 1.5 - 12 + badgeH / 2 + 1);
    ctx.restore();
  }

  function drawBoss(ctx, w, h) {
    const y = gateScreenY({ at: FINISH + 0.28 }, h);
    if (y > h + 100) return;
    const castleSize = clamp(w * 0.5, 150, 250);
    const ogreSize = clamp(w * 0.34, 105, 170);
    ctx.save();
    drawSprite(ctx, "castle", w * 0.5, y - castleSize * 0.18, castleSize);
    const defeated = state.phase === "won" || (state.phase === "battle" && state.count >= BOSS_HP && state.battleT > 0.9);
    ctx.globalAlpha = defeated ? 0.35 : 1;
    drawSprite(ctx, "ogre", w * 0.5, y + castleSize * 0.26, ogreSize, {
      rot: defeated ? 0.3 : Math.sin(state.time * 3) * 0.025,
    });
    ctx.restore();

    if (y < h * 0.62) {
      const hpW = w * 0.5;
      const hpX = w / 2 - hpW / 2;
      const hpY = Math.max(66, y - castleSize * 0.58);
      ctx.save();
      ctx.fillStyle = "rgba(20, 12, 30, 0.55)";
      roundRect(ctx, hpX, hpY, hpW, 11, 6);
      ctx.fill();
      const fill = state.phase === "battle" ? clamp(1 - state.battleT / 1.5, 0, 1) : 1;
      ctx.fillStyle = "#ff5d6c";
      roundRect(ctx, hpX + 1.5, hpY + 1.5, (hpW - 3) * fill, 8, 5);
      ctx.fill();
      ctx.fillStyle = "#fff";
      ctx.font = `900 ${Math.round(clamp(w * 0.024, 9, 12))}px ${DISPLAY}`;
      ctx.textAlign = "center";
      ctx.fillText(`BOSS ${BOSS_HP}`, w / 2, hpY - 5);
      ctx.restore();
    }
  }

  function drawHud(ctx, w, h) {
    const pad = 11;
    const pillH = clamp(h * 0.042, 27, 34);

    ctx.save();
    ctx.fillStyle = "rgba(20, 12, 30, 0.55)";
    roundRect(ctx, pad, pad, clamp(w * 0.27, 96, 124), pillH, 9);
    ctx.fill();
    ctx.fillStyle = "#fff";
    ctx.font = `900 ${Math.round(pillH * 0.45)}px ${DISPLAY}`;
    ctx.textAlign = "left";
    ctx.textBaseline = "middle";
    ctx.fillText(`SQUAD  ${state.count}`, pad + 11, pad + pillH / 2 + 1);

    const bossW = clamp(w * 0.25, 84, 112);
    ctx.fillStyle = "rgba(20, 12, 30, 0.55)";
    roundRect(ctx, w - pad - bossW, pad, bossW, pillH, 9);
    ctx.fill();
    ctx.fillStyle = "#ff9fb0";
    ctx.font = `900 ${Math.round(pillH * 0.42)}px ${DISPLAY}`;
    ctx.textAlign = "center";
    ctx.fillText(state.count >= BOSS_HP ? `BOSS READY ✓` : `NEED ${BOSS_HP}`, w - pad - bossW / 2, pad + pillH / 2 + 1);

    // progress
    const barW = w - pad * 2;
    const barY = pad + pillH + 8;
    ctx.fillStyle = "rgba(20, 12, 30, 0.18)";
    roundRect(ctx, pad, barY, barW, 5, 3);
    ctx.fill();
    ctx.fillStyle = state.count >= BOSS_HP ? "#2ee6a6" : "#ffd23f";
    roundRect(ctx, pad, barY, barW * clamp(state.progress / FINISH, 0, 1), 5, 3);
    ctx.fill();
    ctx.restore();
  }

  function drawFloats(ctx) {
    for (const f of state.floats) {
      const t = f.life / f.max;
      ctx.save();
      ctx.globalAlpha = clamp(t * 1.7, 0, 1);
      ctx.fillStyle = f.color;
      ctx.strokeStyle = "rgba(20,12,30,0.5)";
      ctx.lineWidth = 4;
      ctx.font = `900 ${Math.round(clamp(stage.w * 0.075, 20, 30) * f.size)}px ${DISPLAY}`;
      ctx.textAlign = "center";
      ctx.strokeText(f.text, f.x, f.y);
      ctx.fillText(f.text, f.x, f.y);
      ctx.restore();
    }
  }

  function drawParticles(ctx) {
    for (const p of state.particles) {
      const a = clamp(p.life / p.max, 0, 1);
      ctx.globalAlpha = a;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * a + 0.5, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  function draw() {
    const { ctx } = stage;
    const w = stage.w;
    const h = stage.h;
    ctx.save();
    if (state.shake > 0) {
      ctx.translate(rand(-state.shake, state.shake), rand(-state.shake, state.shake));
    }

    drawBackdrop(ctx, w, h);

    // draw world objects, sorted by depth
    const objects = [];
    for (const gate of state.gates) objects.push({ type: "gate", y: gateScreenY(gate, h), gate });
    for (const p of state.pickups) objects.push({ type: "pickup", y: gateScreenY(p, h), p });
    objects.sort((a, b) => a.y - b.y);

    for (const obj of objects) {
      if (obj.type === "gate") drawGate(ctx, obj.gate, w, h);
      else drawPickup(ctx, obj.p, w, h);
    }

    drawBoss(ctx, w, h);
    drawCrowd(ctx, w, h);
    drawParticles(ctx);
    drawFloats(ctx);
    drawHud(ctx, w, h);

    if (state.flash > 0) {
      ctx.globalAlpha = state.flash * 0.22;
      ctx.fillStyle = "#fff";
      ctx.fillRect(0, 0, w, h);
    }

    if (state.phase === "battle") {
      const t = state.battleT;
      if (t < 1.5) {
        ctx.save();
        ctx.globalAlpha = clamp(1 - t * 0.6, 0, 1);
        ctx.fillStyle = "#20142e";
        ctx.font = `900 ${Math.round(clamp(w * 0.1, 28, 44))}px ${DISPLAY}`;
        ctx.textAlign = "center";
        ctx.strokeStyle = "#ffd23f";
        ctx.lineWidth = 8;
        ctx.strokeText("BOSS FIGHT!", w / 2, h * 0.32);
        ctx.fillText("BOSS FIGHT!", w / 2, h * 0.32);
        ctx.restore();
      }
    }

    ctx.restore();
  }

  const loop = createLoop((dt) => {
    update(dt);
    draw();
  });

  return {
    destroy() {
      loop.stop();
      input.destroy();
      stopPointer();
      stage.destroy();
    },
  };
}

import {
  createStage, createLoop, bindPointer, createKeyboard,
  clamp, lerp, rand, roundRect, TAU, angleDiff, easeOutCubic,
} from "../util.js";
import { drawSprite } from "../sprites.js";
import { audio } from "../audio.js";

const DISPLAY = '"Arial Rounded MT Bold", "Trebuchet MS", system-ui, sans-serif';
const TOTAL = 15;
const APPLE_AT_HITS = [2, 6, 10];

export function mount(root, api) {
  root.innerHTML = "";
  const stage = createStage(root);
  const input = createKeyboard();

  const state = {
    rot: rand(-0.4, 0.4),
    dir: Math.random() < 0.5 ? 1 : -1,
    hits: 0,
    apples: [],
    applesSpawned: 0,
    applesCollected: 0,
    stuck: [],
    phase: "ready",
    flight: 0,
    crashT: 0,
    resultAt: 0,
    shake: 0,
    time: 0,
    spawnBurst: 0,
    particles: [],
    flash: 0,
    ended: false,
  };

  const stopPointer = bindPointer(stage.canvas, {
    down() { throwKnife(); },
  });

  function currentSpeed() {
    return 1.32 + state.hits * 0.125;
  }

  function throwKnife() {
    if (state.phase !== "ready" || state.ended) return;
    state.phase = "flying";
    state.flight = 0;
    audio.whoosh();
    api.vibrate?.(8);
  }

  function popParticles(x, y, color, amount = 12) {
    for (let i = 0; i < amount; i++) {
      const a = rand(0, TAU);
      const sp = rand(50, 240);
      state.particles.push({
        x, y,
        vx: Math.cos(a) * sp,
        vy: Math.sin(a) * sp,
        life: rand(0.25, 0.6),
        max: 0.6,
        size: rand(1.5, 4.5),
        color,
      });
    }
  }

  function spawnAppleIfNeeded() {
    if (state.applesSpawned >= 3) return;
    const threshold = APPLE_AT_HITS[state.applesSpawned];
    if (state.hits < threshold) return;
    const candidates = [];
    for (let tries = 0; tries < 100; tries++) {
      const rel = rand(0, TAU);
      const okKnife = state.stuck.every((k) => angleDiff(k.rel, rel) > 0.52);
      const okApple = state.apples.every((a) => angleDiff(a.rel, rel) > 0.5);
      if (okKnife && okApple) { candidates.push(rel); break; }
    }
    if (candidates.length) {
      state.apples.push({ rel: candidates[0], born: state.time, pulse: rand(0, TAU) });
      state.applesSpawned++;
      state.spawnBurst = 0.55;
      audio.levelUp();
    }
  }

  function impact() {
    const newRel = ((Math.PI / 2 - state.rot) % TAU + TAU) % TAU;
    const { w, h } = stage;
    const cx = w / 2;
    const cy = h * 0.4;
    const radius = Math.min(w * 0.29, h * 0.185);
    const hitX = cx + Math.cos(Math.PI / 2) * (radius + 8);
    const hitY = cy + Math.sin(Math.PI / 2) * (radius + 8);

    const knifeCollision = state.stuck.some((k) => angleDiff(k.rel, newRel) < 0.185);
    if (knifeCollision) {
      state.phase = "crash";
      state.crashT = 0;
      state.shake = 7;
      state.flash = 1;
      audio.bad();
      api.vibrate?.([20, 30, 40]);
      popParticles(hitX, hitY, "#ffd23f", 20);
      return;
    }

    // Did we skewer a golden apple?
    const appleIndex = state.apples.findIndex((a) => angleDiff(a.rel, newRel) < 0.165);
    if (appleIndex >= 0) {
      state.apples.splice(appleIndex, 1);
      state.applesCollected++;
      popParticles(hitX, hitY - 10, "#ffd23f", 24);
      audio.good();
    }

    state.stuck.push({ rel: newRel, born: state.time, wobble: rand(-0.05, 0.05) });
    state.hits++;
    state.phase = "ready";
    state.shake = 4;
    audio.thunk();
    api.vibrate?.(14);

    if (state.hits >= TOTAL && !state.ended) {
      state.ended = true;
      state.phase = "won";
      state.resultAt = 0.7;
      audio.win();
      const stars = state.applesCollected >= 3 ? 3 : state.applesCollected >= 1 ? 2 : 1;
      setTimeout(() => {
        api.win(stars, state.applesCollected, {
          note: state.applesCollected >= 3
            ? "All three golden apples. The algorithm is impressed."
            : `You collected ${state.applesCollected} of 3 golden apples. There is always next ad.`,
        });
      }, 700);
      return;
    }
    spawnAppleIfNeeded();
  }

  function update(dt) {
    state.time += dt;
    input.endFrame();
    state.shake = Math.max(0, state.shake - dt * 16);
    state.flash = Math.max(0, state.flash - dt * 2.8);
    state.spawnBurst = Math.max(0, state.spawnBurst - dt);

    if (state.phase !== "crash" && state.phase !== "won") {
      state.rot += state.dir * currentSpeed() * dt;
      if (state.rot > TAU * 3) state.rot -= TAU * 3;
      if (state.rot < -TAU * 3) state.rot += TAU * 3;
    } else if (state.phase === "crash") {
      state.rot += state.dir * currentSpeed() * dt * 0.25;
      state.crashT += dt;
      if (state.crashT > 0.85 && !state.ended) {
        state.ended = true;
        api.lose("You hit one of your own knives. Extremely on-brand for this ad.");
      }
    } else if (state.phase === "won") {
      state.rot += state.dir * currentSpeed() * dt * 0.3;
    }

    if (state.phase === "flying") {
      state.flight += dt / 0.105;
      if (state.flight >= 1) impact();
    }

    if (input.wasPressed(" ", "spacebar", "arrowup", "w", "enter")) throwKnife();

    for (const p of state.particles) {
      p.life -= dt;
      p.vy += 260 * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
    }
    state.particles = state.particles.filter((p) => p.life > 0);
  }

  function drawBackdrop(ctx, w, h) {
    const g = ctx.createRadialGradient(w / 2, h * 0.4, 20, w / 2, h * 0.4, Math.max(w, h) * 0.85);
    g.addColorStop(0, "#4b1d6e");
    g.addColorStop(0.55, "#2a103f");
    g.addColorStop(1, "#140820");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);

    const cx = w / 2;
    const cy = h * 0.4;
    // target rings
    ctx.save();
    ctx.translate(cx, cy);
    for (let i = 7; i >= 1; i--) {
      ctx.beginPath();
      ctx.arc(0, 0, i * Math.min(w, h) * 0.082, 0, TAU);
      ctx.fillStyle = i % 2 === 0 ? "rgba(255,255,255,0.028)" : "rgba(255,93,140,0.035)";
      ctx.fill();
      ctx.strokeStyle = "rgba(255,255,255,0.05)";
      ctx.lineWidth = 1.5;
      ctx.stroke();
    }
    ctx.restore();

    // floating hearts / sparks
    for (let i = 0; i < 9; i++) {
      const x = ((i * 113 + state.time * (9 + i * 2)) % (w + 40)) - 20;
      const y = (i * 97) % h;
      ctx.globalAlpha = 0.16 + (i % 3) * 0.05;
      ctx.fillStyle = i % 2 ? "#ff5d8c" : "#ffd23f";
      ctx.beginPath();
      ctx.arc(x, y, 2 + (i % 3), 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // floor glow
    const floor = ctx.createLinearGradient(0, h * 0.6, 0, h);
    floor.addColorStop(0, "rgba(255, 93, 140, 0)");
    floor.addColorStop(1, "rgba(255, 93, 140, 0.12)");
    ctx.fillStyle = floor;
    ctx.fillRect(0, h * 0.6, w, h * 0.4);
  }

  function drawLog(ctx, w, h) {
    const cx = w / 2;
    const cy = h * 0.4;
    const radius = Math.min(w * 0.29, h * 0.185);
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(state.rot);

    // shadow/glow
    ctx.save();
    ctx.rotate(-state.rot);
    ctx.fillStyle = "rgba(0,0,0,0.3)";
    ctx.beginPath();
    ctx.ellipse(0, radius + 12, radius * 0.94, 12, 0, 0, TAU);
    ctx.fill();
    ctx.restore();

    const wood = ctx.createRadialGradient(-radius * 0.3, -radius * 0.35, 4, 0, 0, radius);
    wood.addColorStop(0, "#ffe4b3");
    wood.addColorStop(0.52, "#e6b273");
    wood.addColorStop(1, "#a86b3f");
    ctx.beginPath();
    ctx.arc(0, 0, radius, 0, TAU);
    ctx.fillStyle = wood;
    ctx.fill();
    ctx.strokeStyle = "#3d2118";
    ctx.lineWidth = 6;
    ctx.stroke();

    // rings / grain
    for (let i = 1; i <= 4; i++) {
      ctx.beginPath();
      ctx.arc(0, 0, radius * (i / 5.4), 0, TAU);
      ctx.strokeStyle = i % 2 ? "rgba(76, 40, 20, 0.22)" : "rgba(255, 244, 220, 0.18)";
      ctx.lineWidth = i === 1 ? 4 : 2;
      ctx.stroke();
    }
    // knot
    ctx.beginPath();
    ctx.ellipse(radius * 0.3, -radius * 0.18, radius * 0.11, radius * 0.075, 0.5, 0, TAU);
    ctx.fillStyle = "rgba(93, 49, 22, 0.42)";
    ctx.fill();
    ctx.strokeStyle = "rgba(60, 30, 14, 0.5)";
    ctx.lineWidth = 2;
    ctx.stroke();

    // outer bark marks
    for (let i = 0; i < 18; i++) {
      const a = (i / 18) * TAU;
      ctx.save();
      ctx.rotate(a);
      ctx.fillStyle = i % 2 ? "rgba(81, 44, 21, 0.22)" : "rgba(255, 230, 185, 0.14)";
      roundRect(ctx, radius - 8, -2.5, 8, 5, 2);
      ctx.fill();
      ctx.restore();
    }

    // golden apples embedded inside
    for (const apple of state.apples) {
      const a = apple.rel + state.rot;
      const ax = Math.cos(a) * radius * 0.58;
      const ay = Math.sin(a) * radius * 0.58;
      const pulse = 1 + Math.sin(state.time * 6 + apple.pulse) * 0.06;
      ctx.save();
      ctx.translate(ax, ay);
      ctx.rotate(-state.rot);
      ctx.shadowColor = "rgba(255, 210, 63, 0.75)";
      ctx.shadowBlur = 16;
      drawSprite(ctx, "apple", 0, 0, radius * 0.42 * pulse);
      ctx.restore();
    }

    ctx.restore();

    // apple count sparks
    if (state.spawnBurst > 0) {
      ctx.save();
      ctx.globalAlpha = state.spawnBurst;
      ctx.strokeStyle = "#ffd23f";
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(cx, cy, radius * (1 + (0.55 - state.spawnBurst) * 2.6), 0, TAU);
      ctx.stroke();
      ctx.restore();
    }

    // stuck knives (rotate with the log)
    for (const k of state.stuck) {
      const a = k.rel + state.rot;
      const size = clamp(radius * 0.72, 42, 68);
      const r = radius + size * 0.26;
      const x = cx + Math.cos(a) * r;
      const y = cy + Math.sin(a) * r;
      const age = clamp((state.time - k.born) * 9, 0, 1);
      const wobble = Math.sin(state.time * 18 + k.born * 40) * k.wobble * (1 - age);
      drawSprite(ctx, "knife", x, y, size * (0.8 + age * 0.2), { rot: a + Math.PI / 2 + wobble });
    }

    // impact marker at bottom
    ctx.save();
    ctx.translate(cx, cy + radius);
    ctx.rotate(Math.PI / 2);
    ctx.beginPath();
    ctx.moveTo(-6, -11);
    ctx.lineTo(6, -11);
    ctx.lineTo(0, -2);
    ctx.closePath();
    ctx.fillStyle = "rgba(255,255,255,0.65)";
    ctx.fill();
    ctx.restore();
  }

  function drawKnifeInHand(ctx, w, h) {
    if (state.phase !== "ready") return;
    const bob = Math.sin(state.time * 5) * 3;
    const size = clamp(Math.min(w, h) * 0.115, 48, 76);
    const x = w / 2;
    const y = h * 0.845 + bob;

    ctx.save();
    ctx.strokeStyle = "rgba(255,255,255,0.16)";
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 8]);
    ctx.beginPath();
    ctx.moveTo(x, y - size * 0.55);
    ctx.lineTo(x, h * 0.62);
    ctx.stroke();
    ctx.restore();

    drawSprite(ctx, "knife", x, y, size);

    ctx.save();
    ctx.fillStyle = "rgba(255, 210, 63, 0.9)";
    ctx.font = `900 ${Math.round(clamp(w * 0.027, 9, 12))}px ${DISPLAY}`;
    ctx.textAlign = "center";
    ctx.globalAlpha = 0.55 + Math.sin(state.time * 4) * 0.3;
    ctx.fillText("TAP TO THROW", x, y + size * 0.62);
    ctx.restore();
  }

  function drawFlying(ctx, w, h) {
    if (state.phase !== "flying") return;
    const t = easeOutCubic(clamp(state.flight, 0, 1));
    const cx = w / 2;
    const cy = h * 0.4;
    const radius = Math.min(w * 0.29, h * 0.185);
    const startY = h * 0.845;
    const endY = cy + radius + 8;
    const y = lerp(startY, endY, t);
    const size = clamp(Math.min(w, h) * 0.115, 48, 76);

    ctx.save();
    ctx.strokeStyle = "rgba(255,255,255,0.34)";
    ctx.lineWidth = 2;
    for (let i = 0; i < 4; i++) {
      const off = (i - 1.5) * 8;
      ctx.globalAlpha = 0.18 + i * 0.05;
      ctx.beginPath();
      ctx.moveTo(cx + off, y + 22 + i * 16);
      ctx.lineTo(cx + off, y + 50 + i * 22);
      ctx.stroke();
    }
    ctx.restore();
    drawSprite(ctx, "knife", cx, y, size);
  }

  function drawHud(ctx, w, h) {
    const pad = 10;
    const pillH = 27;
    ctx.save();
    ctx.fillStyle = "rgba(12, 6, 20, 0.55)";
    roundRect(ctx, pad, pad, 100, pillH, 8);
    ctx.fill();
    ctx.fillStyle = "#fff";
    ctx.font = `900 10px ${DISPLAY}`;
    ctx.textAlign = "left";
    ctx.textBaseline = "middle";
    ctx.fillText(`KNIVES ${state.hits}/${TOTAL}`, pad + 10, pad + pillH / 2 + 1);

    const count = 3;
    for (let i = 0; i < count; i++) {
      const x = w - pad - 16 - i * 24;
      ctx.globalAlpha = i < state.applesCollected ? 1 : 0.22;
      drawSprite(ctx, "apple", x, pad + pillH / 2, 21);
    }
    ctx.globalAlpha = 1;
    ctx.fillStyle = "rgba(255,255,255,0.35)";
    ctx.font = `800 7px ${DISPLAY}`;
    ctx.textAlign = "right";
    ctx.fillText("GOLDEN APPLES", w - pad - 2, pad + pillH + 10);
    ctx.restore();
  }

  function draw() {
    const { ctx } = stage;
    const w = stage.w;
    const h = stage.h;
    ctx.save();
    if (state.shake > 0.1) ctx.translate(rand(-state.shake, state.shake), rand(-state.shake, state.shake));

    drawBackdrop(ctx, w, h);
    drawLog(ctx, w, h);
    drawHud(ctx, w, h);
    drawKnifeInHand(ctx, w, h);
    drawFlying(ctx, w, h);

    for (const p of state.particles) {
      const a = clamp(p.life / p.max, 0, 1);
      ctx.globalAlpha = a;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    if (state.flash > 0) {
      ctx.fillStyle = `rgba(255, 93, 108, ${state.flash * 0.2})`;
      ctx.fillRect(0, 0, w, h);
    }

    if (state.phase === "crash") {
      ctx.save();
      ctx.globalAlpha = clamp(1 - state.crashT, 0, 1);
      ctx.fillStyle = "#ff5d6c";
      ctx.font = `900 ${Math.round(clamp(w * 0.09, 28, 42))}px ${DISPLAY}`;
      ctx.textAlign = "center";
      ctx.fillText("CLANG!", w / 2, h * 0.25);
      ctx.restore();
    }

    ctx.restore();
  }

  const loop = createLoop((dt) => {
    update(dt);
    draw();
  });

  return {
    destroy() {
      loop.stop();
      input.destroy();
      stopPointer();
      stage.destroy();
    },
  };
}

import {
  createStage, createLoop, bindPointer, createKeyboard,
  clamp, lerp, rand, roundRect, TAU, dist, rotateToward, normAngle, angleDiff,
} from "../util.js";
import { drawSprite } from "../sprites.js";
import { audio } from "../audio.js";

const DISPLAY = '"Arial Rounded MT Bold", "Trebuchet MS", system-ui, sans-serif';
const GOAL = 110;

export function mount(root, api) {
  root.innerHTML = "";
  const stage = createStage(root);
  const input = createKeyboard();

  const state = {
    phase: "play",
    time: 0,
    size: 10,
    angle: -Math.PI / 2,
    targetAngle: -Math.PI / 2,
    head: { x: stage.w / 2, y: stage.h * 0.58 },
    trail: [],
    orbs: [],
    particles: [],
    shake: 0,
    deadT: 0,
    winT: 0,
    eaten: 0,
    pointerSteer: null,
    mouseActive: false,
    joystick: { active: false, x: 0, y: 0, dx: 0, dy: 0 },
    intro: 3.2,
  };

  // seed the tail behind the head
  for (let i = 0; i < 100; i++) {
    state.trail.push({ x: state.head.x, y: state.head.y + i * 4 });
  }

  function headRadius() {
    return clamp(11 + (state.size - 10) * 0.035, 11, 19);
  }

  function bodyLength() {
    return clamp(64 + (state.size - 10) * 1.7, 64, 280);
  }

  function targetCount() {
    return 15;
  }

  function randomOrb() {
    const { w, h } = stage;
    const margin = 32;
    let x = 0;
    let y = 0;
    let ok = false;
    for (let tries = 0; tries < 60; tries++) {
      x = rand(margin, w - margin);
      y = rand(margin, h - margin);
      if (dist(x, y, state.head.x, state.head.y) < Math.min(w, h) * 0.2) continue;
      if (state.orbs.some((o) => dist(x, y, o.x, o.y) < 46)) continue;
      ok = true;
      break;
    }
    if (!ok) {
      x = rand(margin, w - margin);
      y = rand(margin, h - margin);
    }
    const roll = Math.random();
    let value;
    if (roll < 0.48) value = Math.max(2, Math.round(state.size * rand(0.18, 0.68)));
    else if (roll < 0.8) value = Math.max(3, Math.round(state.size * rand(0.82, 1.24)));
    else value = Math.max(4, Math.round(state.size * rand(1.35, 2.15)));
    return {
      x, y, v: value,
      vx: rand(-16, 16),
      vy: rand(-16, 16),
      phase: rand(0, TAU),
      born: rand(0, 0.4),
      r: clamp(12 + Math.log2(value + 1) * 4.1, 15, 31),
    };
  }

  for (let i = 0; i < targetCount(); i++) state.orbs.push(randomOrb());

  const stopPointer = bindPointer(stage.canvas, {
    down(p, e) {
      if (e.pointerType === "mouse") {
        state.mouseActive = true;
        steerTo(p.x, p.y);
      } else {
        state.joystick.active = true;
        state.joystick.x = p.x;
        state.joystick.y = p.y;
        state.joystick.dx = 0;
        state.joystick.dy = 0;
      }
    },
    move(p, e) {
      if (e.pointerType === "mouse") {
        state.mouseActive = true;
        steerTo(p.x, p.y);
      } else if (state.joystick.active) {
        const dx = p.x - state.joystick.x;
        const dy = p.y - state.joystick.y;
        const len = Math.hypot(dx, dy);
        if (len > 14) {
          const capped = Math.min(len, 52);
          state.joystick.dx = (dx / len) * capped;
          state.joystick.dy = (dy / len) * capped;
          state.targetAngle = Math.atan2(dy, dx);
        }
      }
    },
    up() {
      state.joystick.active = false;
      state.joystick.dx = 0;
      state.joystick.dy = 0;
    },
    leave() {
      state.mouseActive = false;
    },
  });

  function steerTo(x, y) {
    const dx = x - state.head.x;
    const dy = y - state.head.y;
    if (Math.hypot(dx, dy) > 20) state.targetAngle = Math.atan2(dy, dx);
  }

  function burst(x, y, color, amount = 10, power = 180) {
    for (let i = 0; i < amount; i++) {
      const a = rand(0, TAU);
      const sp = rand(power * 0.25, power);
      state.particles.push({
        x, y,
        vx: Math.cos(a) * sp,
        vy: Math.sin(a) * sp,
        life: rand(0.3, 0.8),
        max: 0.8,
        size: rand(1.5, 4.5),
        color,
      });
    }
  }

  function eatOrb(orb) {
    state.eaten++;
    const gain = Math.max(2, Math.round(orb.v * 0.78));
    state.size += gain;
    burst(orb.x, orb.y, "#3ee9a5", 20, 250);
    state.orbs.splice(state.orbs.indexOf(orb), 1);
    state.orbs.push(randomOrb());
    audio.eat();
    api.vibrate?.(8);
    if (state.size >= GOAL && state.phase === "play") {
      state.phase = "won";
      state.winT = 0;
      audio.win();
      const stars = state.time <= 35 ? 3 : state.time <= 55 ? 2 : 1;
      setTimeout(() => {
        api.win(stars, Math.round(state.size), {
          note: `Grew to ${Math.round(state.size)} in ${state.time.toFixed(1)}s. The arena respects you now.`,
        });
      }, 650);
    }
  }

  function update(dt) {
    state.time += dt;
    state.intro = Math.max(0, state.intro - dt);
    input.endFrame();
    state.shake = Math.max(0, state.shake - dt * 22);

    if (state.phase === "play") {
      // steering priority: keyboard > touch joystick > mouse
      let kx = 0;
      let ky = 0;
      if (input.isDown("arrowleft", "a")) kx -= 1;
      if (input.isDown("arrowright", "d")) kx += 1;
      if (input.isDown("arrowup", "w")) ky -= 1;
      if (input.isDown("arrowdown", "s")) ky += 1;
      if (kx || ky) state.targetAngle = Math.atan2(ky, kx);
      else if (state.joystick.active) {
        if (Math.hypot(state.joystick.dx, state.joystick.dy) > 4) {
          state.targetAngle = Math.atan2(state.joystick.dy, state.joystick.dx);
        }
      }

      const turn = 5.2 * dt;
      state.angle = rotateToward(state.angle, state.targetAngle, turn);

      const speed = clamp(Math.min(stage.w, stage.h) * 0.57, 150, 250);
      state.head.x += Math.cos(state.angle) * speed * dt;
      state.head.y += Math.sin(state.angle) * speed * dt;

      const pad = headRadius() + 3;
      let clamped = false;
      if (state.head.x < pad) { state.head.x = pad; clamped = true; }
      if (state.head.x > stage.w - pad) { state.head.x = stage.w - pad; clamped = true; }
      if (state.head.y < pad) { state.head.y = pad; clamped = true; }
      if (state.head.y > stage.h - pad) { state.head.y = stage.h - pad; clamped = true; }
      if (clamped) {
        // slide along the wall instead of sticking
        state.targetAngle = state.angle + Math.PI * 0.5;
        state.angle = state.targetAngle;
      }

      // trail sampling
      const last = state.trail[0];
      if (dist(state.head.x, state.head.y, last.x, last.y) > 4.2) {
        state.trail.unshift({ x: state.head.x, y: state.head.y });
      }
      const maxPoints = Math.ceil(bodyLength() / 4.2) + 4;
      if (state.trail.length > maxPoints) state.trail.length = maxPoints;
      // maintain enough tail while growing
      while (state.trail.length < maxPoints) {
        const tail = state.trail[state.trail.length - 1];
        state.trail.push({ x: tail.x - Math.cos(state.angle) * 4, y: tail.y - Math.sin(state.angle) * 4 });
      }

      // orbs drift
      for (const orb of state.orbs) {
        orb.phase += dt;
        orb.x += orb.vx * dt;
        orb.y += orb.vy * dt;
        if (orb.x < orb.r + 16) { orb.x = orb.r + 16; orb.vx = Math.abs(orb.vx); }
        if (orb.x > stage.w - orb.r - 16) { orb.x = stage.w - orb.r - 16; orb.vx = -Math.abs(orb.vx); }
        if (orb.y < orb.r + 16) { orb.y = orb.r + 16; orb.vy = Math.abs(orb.vy); }
        if (orb.y > stage.h - orb.r - 16) { orb.y = stage.h - orb.r - 16; orb.vy = -Math.abs(orb.vy); }
      }

      // collisions
      for (const orb of [...state.orbs]) {
        const rr = headRadius() * 0.72 + orb.r * 0.78;
        if (dist(state.head.x, state.head.y, orb.x, orb.y) < rr) {
          if (orb.v <= state.size) {
            eatOrb(orb);
          } else {
            state.phase = "dead";
            state.deadT = 0;
            state.shake = 12;
            burst(state.head.x, state.head.y, "#ff5d6c", 34, 300);
            audio.bad();
            api.vibrate?.([30, 40, 60]);
            setTimeout(() => {
              api.lose(`You were size ${state.size} and tried to eat a ${orb.v}. Ambition: noted.`);
            }, 850);
          }
          break;
        }
      }
    } else if (state.phase === "won") {
      state.winT += dt;
    } else if (state.phase === "dead") {
      state.deadT += dt;
    }

    for (const p of state.particles) {
      p.life -= dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vx *= 1 - dt * 1.2;
      p.vy *= 1 - dt * 1.2;
    }
    state.particles = state.particles.filter((p) => p.life > 0);
  }

  function drawArena(ctx, w, h) {
    const g = ctx.createRadialGradient(w * 0.5, h * 0.45, 20, w * 0.5, h * 0.5, Math.max(w, h) * 0.78);
    g.addColorStop(0, "#0b2630");
    g.addColorStop(0.55, "#081821");
    g.addColorStop(1, "#050d13");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);

    // dot grid
    ctx.save();
    ctx.fillStyle = "rgba(94, 255, 196, 0.09)";
    const gap = 27;
    for (let y = gap / 2; y < h; y += gap) {
      for (let x = gap / 2; x < w; x += gap) {
        ctx.beginPath();
        ctx.arc(x, y, 1.4, 0, TAU);
        ctx.fill();
      }
    }
    ctx.restore();

    // arena boundary
    ctx.save();
    ctx.strokeStyle = "rgba(62, 233, 165, 0.22)";
    ctx.lineWidth = 3;
    roundRect(ctx, 10, 10, w - 20, h - 20, 20);
    ctx.stroke();
    ctx.strokeStyle = "rgba(62, 233, 165, 0.06)";
    ctx.lineWidth = 10;
    roundRect(ctx, 10, 10, w - 20, h - 20, 20);
    ctx.stroke();
    ctx.restore();

    // ambient motes
    for (let i = 0; i < 12; i++) {
      const x = ((i * 83 + state.time * (6 + i)) % (w + 20)) - 10;
      const y = (i * 147 + Math.sin(state.time * 0.5 + i) * 20) % h;
      ctx.globalAlpha = 0.12 + (i % 3) * 0.04;
      ctx.fillStyle = "#3ee9a5";
      ctx.beginPath();
      ctx.arc(x, y, 1.6, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  function drawOrb(ctx, orb) {
    const edible = orb.v <= state.size;
    const bob = Math.sin(state.time * 3 + orb.phase) * 2.5;
    const size = orb.r * 2.3 * (1 + Math.sin(state.time * 4 + orb.phase) * 0.015);
    const x = orb.x;
    const y = orb.y + bob;

    ctx.save();
    ctx.shadowColor = edible ? "rgba(62, 233, 165, 0.35)" : "rgba(255, 93, 108, 0.38)";
    ctx.shadowBlur = 18;
    drawSprite(ctx, edible ? "orbGreen" : "orbRed", x, y, size, { rot: Math.sin(state.time * 2 + orb.phase) * 0.06 });
    ctx.restore();

    ctx.save();
    ctx.font = `900 ${Math.round(clamp(orb.r * 0.82, 11, 20))}px ${DISPLAY}`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.lineWidth = 3.5;
    ctx.strokeStyle = "rgba(8, 12, 18, 0.65)";
    ctx.strokeText(String(orb.v), x, y + orb.r * 0.08);
    ctx.fillStyle = "#ffffff";
    ctx.fillText(String(orb.v), x, y + orb.r * 0.08);
    ctx.restore();
  }

  function drawSnake(ctx, w, h) {
    const hr = headRadius();
    const points = state.trail;
    const n = points.length;
    if (!n) return;

    // glow
    ctx.save();
    ctx.shadowColor = "rgba(62, 233, 165, 0.55)";
    ctx.shadowBlur = 18;

    // draw from tail to head
    for (let i = n - 1; i >= 0; i--) {
      const t = i / Math.max(1, n - 1);
      const r = hr * lerp(0.28, 1, 1 - t) * (state.phase === "dead" ? 0.9 : 1);
      const p = points[i];
      ctx.beginPath();
      ctx.arc(p.x, p.y, r, 0, TAU);
      const shade = i % 3;
      ctx.fillStyle = shade === 0 ? "#19b97b" : shade === 1 ? "#20cd88" : "#2ee6a0";
      ctx.fill();
    }
    ctx.restore();

    // belly stripe
    ctx.save();
    ctx.strokeStyle = "rgba(190, 255, 226, 0.38)";
    ctx.lineWidth = Math.max(2, hr * 0.34);
    ctx.lineCap = "round";
    ctx.beginPath();
    for (let i = 0; i < n; i += 2) {
      const p = points[i];
      if (i === 0) ctx.moveTo(p.x, p.y);
      else ctx.lineTo(p.x, p.y);
    }
    ctx.stroke();
    ctx.restore();

    // head
    const headSize = hr * 3.6;
    ctx.save();
    ctx.shadowColor = "rgba(62, 233, 165, 0.55)";
    ctx.shadowBlur = 22;
    drawSprite(ctx, "snakeHead", state.head.x, state.head.y, headSize, { rot: state.angle });
    ctx.restore();

    // aim eyes bug out when close to a larger orb
    let danger = null;
    let dangerD = Infinity;
    for (const o of state.orbs) {
      if (o.v > state.size) {
        const d = dist(state.head.x, state.head.y, o.x, o.y);
        if (d < dangerD) { dangerD = d; danger = o; }
      }
    }
    if (danger && dangerD < 110 && state.phase === "play") {
      ctx.save();
      ctx.globalAlpha = clamp(1 - dangerD / 110, 0, 1);
      ctx.fillStyle = "#ff5d6c";
      ctx.font = `900 ${Math.round(clamp(w * 0.03, 10, 14))}px ${DISPLAY}`;
      ctx.textAlign = "center";
      ctx.fillText("!!", state.head.x + Math.cos(state.angle) * 24, state.head.y + Math.sin(state.angle) * 24 - 22);
      ctx.restore();
    }
  }

  function drawJoystick(ctx) {
    if (!state.joystick.active) return;
    const { x, y, dx, dy } = state.joystick;
    ctx.save();
    ctx.globalAlpha = 0.32;
    ctx.strokeStyle = "#ffffff";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(x, y, 42, 0, TAU);
    ctx.stroke();
    ctx.fillStyle = "rgba(255,255,255,0.12)";
    ctx.fill();
    ctx.globalAlpha = 0.7;
    ctx.fillStyle = "#3ee9a5";
    ctx.beginPath();
    ctx.arc(x + dx, y + dy, 16, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  function drawHud(ctx, w, h) {
    const pad = 12;
    const barW = w - pad * 2;
    ctx.save();
    ctx.fillStyle = "rgba(4, 12, 17, 0.62)";
    roundRect(ctx, pad, pad, barW, 36, 10);
    ctx.fill();
    ctx.strokeStyle = "rgba(62, 233, 165, 0.2)";
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.fillStyle = "#dffdf2";
    ctx.font = `900 10px ${DISPLAY}`;
    ctx.textAlign = "left";
    ctx.textBaseline = "middle";
    ctx.fillText(`SIZE ${Math.round(state.size)}`, pad + 10, pad + 13);

    const time = state.time;
    const mm = Math.floor(time / 60);
    const ss = Math.floor(time % 60);
    ctx.textAlign = "right";
    ctx.fillStyle = "rgba(223, 253, 242, 0.7)";
    ctx.fillText(`${mm}:${ss.toString().padStart(2, "0")}`, w - pad - 10, pad + 13);

    const bx = pad + 10;
    const by = pad + 23;
    const bw = barW - 20;
    ctx.fillStyle = "rgba(255,255,255,0.12)";
    roundRect(ctx, bx, by, bw, 5, 3);
    ctx.fill();
    const prog = clamp((state.size - 10) / (GOAL - 10), 0, 1);
    const grad = ctx.createLinearGradient(bx, 0, bx + bw, 0);
    grad.addColorStop(0, "#3ee9a5");
    grad.addColorStop(1, "#ffd23f");
    ctx.fillStyle = grad;
    roundRect(ctx, bx, by, bw * prog, 5, 3);
    ctx.fill();

    ctx.fillStyle = "rgba(223, 253, 242, 0.45)";
    ctx.font = `800 7.5px ${DISPLAY}`;
    ctx.textAlign = "right";
    ctx.fillText(`GOAL ${GOAL}`, w - pad - 10, pad + 37 + 7);
    ctx.restore();
  }

  function draw() {
    const { ctx } = stage;
    const w = stage.w;
    const h = stage.h;
    ctx.save();
    if (state.shake > 0.1) ctx.translate(rand(-state.shake, state.shake), rand(-state.shake, state.shake));

    drawArena(ctx, w, h);
    for (const orb of state.orbs) drawOrb(ctx, orb);
    drawSnake(ctx, w, h);

    for (const p of state.particles) {
      const a = clamp(p.life / p.max, 0, 1);
      ctx.globalAlpha = a;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    drawJoystick(ctx);
    drawHud(ctx, w, h);

    if (state.intro > 0 && state.phase === "play") {
      const a = clamp(state.intro > 2.7 ? (3.2 - state.intro) * 2 : state.intro / 1.2, 0, 1);
      ctx.save();
      ctx.globalAlpha = a * 0.9;
      ctx.fillStyle = "#dffdf2";
      ctx.font = `900 ${Math.round(clamp(w * 0.06, 18, 26))}px ${DISPLAY}`;
      ctx.textAlign = "center";
      ctx.fillText("EAT SMALLER", w / 2, h * 0.2);
      ctx.fillStyle = "#ff9fb0";
      ctx.fillText("AVOID BIGGER", w / 2, h * 0.2 + 29);
      ctx.restore();
    }

    if (state.phase === "dead") {
      ctx.save();
      ctx.globalAlpha = clamp(1 - state.deadT * 0.7, 0, 1);
      ctx.fillStyle = "rgba(255, 93, 108, 0.12)";
      ctx.fillRect(0, 0, w, h);
      ctx.restore();
    }

    ctx.restore();
  }

  const loop = createLoop((dt) => {
    update(dt);
    draw();
  });

  return {
    destroy() {
      loop.stop();
      input.destroy();
      stopPointer();
      stage.destroy();
    },
  };
}

import {
  createStage, createLoop, bindPointer,
  clamp, lerp, rand, roundRect, TAU, easeOutCubic,
} from "../util.js";
import { audio } from "../audio.js";

const DISPLAY = '"Arial Rounded MT Bold", "Trebuchet MS", system-ui, sans-serif';
const CAP = 4;
const START = [
  [1, 1, 0, 2],
  [3, 3, 2, 0],
  [3, 2, 1, 0],
  [2, 3, 0, 1],
  [],
  [],
];
const PALETTE = [
  { base: "#ff5d6c", light: "#ffb3bd", dark: "#c72c47" },
  { base: "#5b9dff", light: "#b8d4ff", dark: "#2f62c9" },
  { base: "#ffd23f", light: "#fff0a8", dark: "#c08d00" },
  { base: "#3ee9a5", light: "#b9ffe1", dark: "#0e9c68" },
];

export function mount(root, api) {
  root.innerHTML = "";
  const stage = createStage(root);

  const state = {
    tubes: START.map((t) => t.slice()),
    history: [],
    moves: 0,
    selected: -1,
    render: [],
    pour: null,
    time: 0,
    ended: false,
    shake: 0,
    sparkles: [],
    hover: -1,
    lift: START.map(() => 0),
  };

  resetRender();

  const toolbar = document.createElement("div");
  toolbar.className = "sort-toolbar";
  toolbar.innerHTML = `
    <span class="hud-pill">MOVES <b class="accent" id="sort-moves">0</b></span>
    <button class="hud-btn" id="sort-undo" type="button" aria-label="Undo last pour">↶ UNDO</button>
  `;
  root.appendChild(toolbar);
  const movesEl = toolbar.querySelector("#sort-moves");
  const undoBtn = toolbar.querySelector("#sort-undo");

  function resetRender() {
    state.render = state.tubes.map((t, i) => ({
      stack: t.slice(),
      count: t.length,
      target: t.length,
      index: i,
    }));
  }

  function topGroup(tube) {
    if (!tube.length) return { color: null, count: 0 };
    const color = tube[tube.length - 1];
    let count = 1;
    while (count < tube.length && tube[tube.length - 1 - count] === color) count++;
    return { color, count };
  }

  function canPour(from, to) {
    if (from === to) return false;
    const src = state.tubes[from];
    const dst = state.tubes[to];
    if (!src.length || dst.length >= CAP) return false;
    const top = src[src.length - 1];
    if (dst.length && dst[dst.length - 1] !== top) return false;
    return true;
  }

  function amountFor(from, to) {
    const { count } = topGroup(state.tubes[from]);
    return Math.min(count, CAP - state.tubes[to].length);
  }

  function layout() {
    const w = stage.w;
    const h = stage.h;
    const margin = w * 0.11;
    const colGap = (w - margin * 2) / 3;
    const tubeW = Math.min(colGap * 0.62, 68);
    const tubeH = Math.min(h * 0.3, 196);
    const positions = [];
    for (let row = 0; row < 2; row++) {
      for (let col = 0; col < 3; col++) {
        positions.push({
          x: margin + colGap * col + colGap / 2 - tubeW / 2,
          y: h * (row === 0 ? 0.335 : 0.715) - tubeH / 2,
          w: tubeW,
          h: tubeH,
          cx: margin + colGap * col + colGap / 2,
          cy: h * (row === 0 ? 0.335 : 0.715),
        });
      }
    }
    return positions;
  }

  function hitTest(x, y) {
    const positions = layout();
    for (let i = 0; i < positions.length; i++) {
      const p = positions[i];
      if (x >= p.x - 10 && x <= p.x + p.w + 10 && y >= p.y - 18 && y <= p.y + p.h + 14) return i;
    }
    return -1;
  }

  function resetLevel() {
    state.tubes = START.map((t) => t.slice());
    state.history = [];
    state.moves = 0;
    state.selected = -1;
    state.pour = null;
    state.ended = false;
    resetRender();
    updateToolbar();
  }

  function updateToolbar() {
    movesEl.textContent = String(state.moves);
    undoBtn.disabled = state.history.length === 0;
  }

  function doPour(from, to) {
    const amount = amountFor(from, to);
    const color = state.tubes[from][state.tubes[from].length - 1];
    state.history.push({
      tubes: state.tubes.map((t) => t.slice()),
      moves: state.moves,
    });
    const oldFrom = state.tubes[from].slice();
    const oldTo = state.tubes[to].slice();
    for (let i = 0; i < amount; i++) {
      state.tubes[from].pop();
      state.tubes[to].push(color);
    }
    state.moves++;

    // Reconstruct the old source stack for a smooth drain animation.
    state.render[from] = {
      stack: [...state.tubes[from], ...Array(amount).fill(color)],
      count: oldFrom.length,
      target: state.tubes[from].length,
      index: from,
    };
    state.render[to] = {
      stack: state.tubes[to].slice(),
      count: oldTo.length,
      target: state.tubes[to].length,
      index: to,
    };
    state.pour = { from, to, color, amount, t: 0, dur: 0.28, oldest: oldFrom.length };
    state.selected = -1;
    audio.splash();
    api.vibrate?.(10);
    updateToolbar();
    checkWin();
  }

  function checkWin() {
    const done = state.tubes.every((t) => t.length === 0 || (t.length === CAP && t.every((c) => c === t[0])));
    if (!done || state.ended) return;
    state.ended = true;
    const stars = state.moves <= 13 ? 3 : state.moves <= 18 ? 2 : 1;
    audio.win();
    setTimeout(() => {
      api.win(stars, state.moves, {
        note: state.moves <= 13
          ? "That was almost optimal pouring. The wizard is suspicious."
          : "All four potions sorted. The ad only needed you to tap once, allegedly.",
      });
    }, 600);
  }

  function handleTubeTap(index) {
    if (state.ended || state.pour) return;
    if (index < 0) {
      state.selected = -1;
      return;
    }
    if (state.selected === -1) {
      if (state.tubes[index].length) {
        state.selected = index;
        audio.tap();
      }
      return;
    }
    if (state.selected === index) {
      state.selected = -1;
      audio.click();
      return;
    }
    if (canPour(state.selected, index)) {
      doPour(state.selected, index);
    } else {
      audio.click();
      state.shake = 0.28;
      if (state.tubes[index].length) state.selected = index;
      else state.selected = -1;
    }
  }

  const stopPointer = bindPointer(stage.canvas, {
    down(p) {
      handleTubeTap(hitTest(p.x, p.y));
    },
  });

  undoBtn.addEventListener("click", () => {
    if (!state.history.length || state.ended) return;
    const prev = state.history.pop();
    state.tubes = prev.tubes.map((t) => t.slice());
    state.moves = prev.moves;
    state.selected = -1;
    state.pour = null;
    resetRender();
    updateToolbar();
    audio.click();
  });

  function update(dt) {
    state.time += dt;
    state.shake = Math.max(0, state.shake - dt);
    if (state.pour) {
      state.pour.t += dt;
      if (state.pour.t >= state.pour.dur + 0.08) {
        state.pour = null;
      }
    }
    for (let i = 0; i < state.render.length; i++) {
      const r = state.render[i];
      if (Math.abs(r.count - r.target) > 0.01) {
        const speed = state.pour && state.pour.t < 0.3 ? 22 : 14;
        r.count = lerp(r.count, r.target, clamp(speed * dt, 0, 1));
        if (Math.abs(r.count - r.target) < 0.02) {
          r.count = r.target;
          r.stack = state.tubes[i].slice();
        }
      } else {
        r.count = r.target;
        r.stack = state.tubes[i].slice();
      }
      const targetLift = state.selected === i ? 1 : 0;
      state.lift[i] = lerp(state.lift[i], targetLift, clamp(12 * dt, 0, 1));
    }
    for (const s of state.sparkles) {
      s.life -= dt;
      s.x += s.vx * dt;
      s.y += s.vy * dt;
      s.vy += 180 * dt;
    }
    state.sparkles = state.sparkles.filter((s) => s.life > 0);
  }

  function colorFor(index, shade = "base") {
    return PALETTE[index]?.[shade] || "#fff";
  }

  function drawBackground(ctx, w, h) {
    const g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, "#2b1550");
    g.addColorStop(0.55, "#1b0e35");
    g.addColorStop(1, "#110722");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);

    // moon glow
    const glow = ctx.createRadialGradient(w * 0.5, h * 0.12, 10, w * 0.5, h * 0.2, w * 0.8);
    glow.addColorStop(0, "rgba(155, 92, 255, 0.28)");
    glow.addColorStop(1, "rgba(155, 92, 255, 0)");
    ctx.fillStyle = glow;
    ctx.fillRect(0, 0, w, h);

    // arcane stars
    for (let i = 0; i < 26; i++) {
      const x = ((i * 79.7) % w);
      const y = ((i * 131.3) % (h * 0.9));
      const tw = 0.35 + Math.sin(state.time * 2 + i) * 0.25;
      ctx.globalAlpha = clamp(tw, 0.05, 0.7);
      ctx.fillStyle = i % 5 === 0 ? "#ffd23f" : "#d7c4ff";
      ctx.beginPath();
      ctx.arc(x, y, i % 7 === 0 ? 2.2 : 1.2, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // shelves
    const positions = layout();
    const y1 = positions[0].y + positions[0].h + 18;
    const y2 = positions[3].y + positions[3].h + 18;
    for (const y of [y1, y2]) {
      const grad = ctx.createLinearGradient(0, y, 0, y + 12);
      grad.addColorStop(0, "rgba(255,255,255,0.15)");
      grad.addColorStop(1, "rgba(255,255,255,0.02)");
      ctx.fillStyle = grad;
      roundRect(ctx, w * 0.07, y, w * 0.86, 9, 5);
      ctx.fill();
      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1;
      ctx.stroke();
    }

    // bottom vignette
    const vign = ctx.createLinearGradient(0, h * 0.78, 0, h);
    vign.addColorStop(0, "rgba(7,3,12,0)");
    vign.addColorStop(1, "rgba(7,3,12,0.6)");
    ctx.fillStyle = vign;
    ctx.fillRect(0, h * 0.78, w, h * 0.22);
  }

  function drawTube(ctx, index, position, positions) {
    const w = stage.w;
    const lift = state.lift[index] * 9;
    const { x, w: tw, h: th } = position;
    const y = position.y - lift;
    const cx = x + tw / 2;
    const isSelected = state.selected === index;
    const validTarget = state.selected >= 0 && state.selected !== index
      && canPour(state.selected, index)
      && !state.pour;
    const completing = state.tubes[index].length === CAP
      && state.tubes[index].every((c) => c === state.tubes[index][0]);
    const r = state.render[index];

    ctx.save();

    if (isSelected || validTarget || completing) {
      ctx.save();
      const glowColor = isSelected
        ? "#ffd23f"
        : completing ? "#3ee9a5" : colorFor(topGroup(state.tubes[state.selected] || []).color || 0, "base");
      ctx.globalAlpha = isSelected ? 0.55 : validTarget ? 0.22 + Math.sin(state.time * 5) * 0.09 : 0.4;
      ctx.strokeStyle = glowColor;
      ctx.lineWidth = 3;
      roundRect(ctx, x - 8, y - 10, tw + 16, th + 20, tw * 0.38);
      ctx.stroke();
      ctx.restore();
    }

    // glass body
    const glass = ctx.createLinearGradient(x, y, x + tw, y + th);
    glass.addColorStop(0, "rgba(255,255,255,0.14)");
    glass.addColorStop(0.22, "rgba(255,255,255,0.045)");
    glass.addColorStop(0.75, "rgba(255,255,255,0.02)");
    glass.addColorStop(1, "rgba(255,255,255,0.1)");
    ctx.fillStyle = glass;
    roundRect(ctx, x, y, tw, th, tw * 0.32);
    ctx.fill();

    // liquid
    const inset = 5;
    const bottom = y + th - 9;
    const top = y + 14;
    const innerH = bottom - top;
    const unit = innerH / CAP;
    const lx = x + inset;
    const lw = tw - inset * 2;
    ctx.save();
    roundRect(ctx, x + 2, y + 9, tw - 4, th - 12, tw * 0.3);
    ctx.clip();

    const layers = Math.ceil(r.count - 0.0001);
    for (let j = 0; j < layers; j++) {
      const colorIndex = r.stack[j];
      if (colorIndex == null) continue;
      const frac = clamp(r.count - j, 0, 1);
      const layerBottom = bottom - j * unit;
      const layerTop = layerBottom - unit * frac;
      const grad = ctx.createLinearGradient(lx, 0, lx + lw, 0);
      grad.addColorStop(0, colorFor(colorIndex, "dark"));
      grad.addColorStop(0.22, colorFor(colorIndex, "base"));
      grad.addColorStop(0.72, colorFor(colorIndex, "base"));
      grad.addColorStop(1, colorFor(colorIndex, "light"));
      ctx.fillStyle = grad;
      ctx.fillRect(lx, layerTop, lw, layerBottom - layerTop);
      ctx.fillStyle = colorFor(colorIndex, "light");
      ctx.globalAlpha = 0.28;
      ctx.fillRect(lx, layerTop, lw * 0.18, layerBottom - layerTop);
      ctx.globalAlpha = 1;
      if (j === layers - 1 && frac < 0.99) {
        ctx.fillStyle = colorFor(colorIndex, "light");
        ctx.globalAlpha = 0.65;
        ctx.beginPath();
        ctx.ellipse(cx, layerTop, lw / 2, Math.max(2, lw * 0.1), 0, 0, TAU);
        ctx.fill();
        ctx.globalAlpha = 1;
      }
    }

    // bubbles
    ctx.globalAlpha = 0.22;
    ctx.fillStyle = "#fff";
    for (let b = 0; b < 3; b++) {
      const bx = lx + lw * (0.22 + ((index * 7 + b * 3) % 6) * 0.11);
      const by = bottom - ((state.time * (8 + b * 3) + b * 37 + index * 23) % Math.max(1, innerH));
      ctx.beginPath();
      ctx.arc(bx, by, 1.3 + b * 0.5, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    ctx.restore();

    // glass shine + outline
    ctx.save();
    ctx.strokeStyle = "rgba(255,255,255,0.27)";
    ctx.lineWidth = 2;
    roundRect(ctx, x, y, tw, th, tw * 0.32);
    ctx.stroke();
    ctx.fillStyle = "rgba(255,255,255,0.18)";
    roundRect(ctx, x + tw * 0.13, y + th * 0.08, tw * 0.1, th * 0.76, tw * 0.06);
    ctx.fill();
    ctx.fillStyle = "rgba(255,255,255,0.1)";
    roundRect(ctx, x + tw * 0.78, y + th * 0.12, tw * 0.045, th * 0.3, tw * 0.04);
    ctx.fill();
    ctx.restore();

    // rim
    ctx.save();
    ctx.strokeStyle = "rgba(255,255,255,0.42)";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.ellipse(cx, y + 7, tw * 0.5, 5, 0, 0, TAU);
    ctx.stroke();
    ctx.fillStyle = "rgba(10, 5, 20, 0.5)";
    ctx.beginPath();
    ctx.ellipse(cx, y + 7, tw * 0.44, 3.8, 0, 0, TAU);
    ctx.fill();
    ctx.restore();

    // completing sparkle
    if (completing) {
      ctx.save();
      ctx.globalAlpha = 0.5 + Math.sin(state.time * 4) * 0.2;
      ctx.fillStyle = "#ffd23f";
      ctx.font = `900 ${Math.round(tw * 0.3)}px ${DISPLAY}`;
      ctx.textAlign = "center";
      ctx.fillText("★", cx, y - 12);
      ctx.restore();
    }

    ctx.restore();
  }

  function drawPour(ctx) {
    if (!state.pour) return;
    const t = clamp(state.pour.t / state.pour.dur, 0, 1);
    const positions = layout();
    const from = positions[state.pour.from];
    const to = positions[state.pour.to];
    if (!from || !to) return;
    const fx = from.cx;
    const fy = from.y - 4;
    const tx = to.cx;
    const ty = to.y - 4;
    const midX = (fx + tx) / 2;
    const minY = Math.min(fy, ty) - 50;
    const color = colorFor(state.pour.color, "base");
    ctx.save();
    ctx.globalAlpha = t < 0.9 ? 0.9 : (1 - t) / 0.1;
    ctx.strokeStyle = color;
    ctx.lineWidth = 7;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(fx, fy);
    ctx.quadraticCurveTo(midX, minY, tx, ty);
    ctx.stroke();
    ctx.strokeStyle = "rgba(255,255,255,0.5)";
    ctx.lineWidth = 2;
    ctx.stroke();
    // droplets
    const steps = 5;
    for (let i = 0; i < steps; i++) {
      const q = (t * 1.6 - i * 0.12) % 1;
      if (q < 0 || q > 1) continue;
      const x = (1 - q) ** 2 * fx + 2 * (1 - q) * q * midX + q * q * tx;
      const y = (1 - q) ** 2 * fy + 2 * (1 - q) * q * minY + q * q * ty;
      ctx.globalAlpha = 0.6 * (1 - q);
      ctx.fillStyle = "#fff";
      ctx.beginPath();
      ctx.arc(x, y, 2.2, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }

  function draw() {
    const { ctx } = stage;
    const w = stage.w;
    const h = stage.h;
    ctx.save();
    if (state.shake > 0) {
      ctx.translate(rand(-3, 3) * state.shake * 3, rand(-1, 1) * state.shake * 3);
    }
    drawBackground(ctx, w, h);

    const positions = layout();
    for (let i = 0; i < positions.length; i++) drawTube(ctx, i, positions[i], positions);
    drawPour(ctx);

    for (const s of state.sparkles) {
      const a = clamp(s.life / s.max, 0, 1);
      ctx.globalAlpha = a;
      ctx.fillStyle = s.color;
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r * a, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // little label
    ctx.save();
    ctx.fillStyle = "rgba(255,255,255,0.28)";
    ctx.font = `800 8px ${DISPLAY}`;
    ctx.textAlign = "center";
    ctx.fillText("TAP A TUBE · TAP ANOTHER TO POUR", w / 2, h - 15);
    ctx.restore();

    ctx.restore();
  }

  updateToolbar();

  const loop = createLoop((dt) => {
    update(dt);
    draw();
  });

  return {
    destroy() {
      loop.stop();
      stopPointer();
      toolbar.remove();
      stage.destroy();
    },
  };
}

import {
  createStage, createLoop, bindPointer,
  clamp, lerp, rand, roundRect, TAU, dist, easeOutCubic,
} from "../util.js";
import { drawSprite } from "../sprites.js";
import { audio } from "../audio.js";

const DISPLAY = '"Arial Rounded MT Bold", "Trebuchet MS", system-ui, sans-serif';
const DURATION = 20;
const LINE_LIFE = 7;
const LINE_WIDTH = 9;
const SPAWN_TIMES = [
  0.8, 1.7, 2.5, 3.4, 4.3, 5.2, 6.2, 7.1, 8.0, 8.4,
  9.5, 10.6, 11.7, 12.8, 13.2, 14.3, 15.3, 16.2, 17.2, 18.1,
];

export function mount(root, api) {
  root.innerHTML = "";
  const stage = createStage(root);

  const state = {
    phase: "play",
    time: 0,
    hearts: 3,
    ink: 700,
    maxInk: 800,
    lines: [],
    drawing: null,
    bees: [],
    spawnIndex: 0,
    particles: [],
    blocked: 0,
    shake: 0,
    flash: 0,
    dogFlash: 0,
    bubble: { text: "HELP!", life: 2.6 },
    ended: false,
    winT: 0,
    loseT: 0,
    tickle: 0,
  };

  const dog = () => ({
    x: stage.w / 2,
    y: stage.h * 0.84,
    size: clamp(Math.min(stage.w, stage.h) * 0.27, 88, 124),
    radius: clamp(Math.min(stage.w, stage.h) * 0.085, 26, 38),
  });

  const stopPointer = bindPointer(stage.canvas, {
    down(p) {
      if (state.phase !== "play" || state.ink < 10) return;
      state.drawing = { points: [{ x: p.x, y: p.y }], born: state.time };
      audio.tap();
    },
    move(p) {
      if (!state.drawing || state.phase !== "play") return;
      const pts = state.drawing.points;
      const last = pts[pts.length - 1];
      const d = dist(last.x, last.y, p.x, p.y);
      if (d < 6) return;
      const step = Math.min(d, 18);
      const nx = last.x + ((p.x - last.x) / d) * step;
      const ny = last.y + ((p.y - last.y) / d) * step;
      if (state.ink < step) {
        finishLine();
        return;
      }
      state.ink -= step;
      pts.push({ x: nx, y: ny });
      if (pts.length > 220) finishLine();
    },
    up() { finishLine(); },
    leave() { finishLine(); },
  });

  function finishLine() {
    if (!state.drawing) return;
    const line = state.drawing;
    state.drawing = null;
    if (line.points.length < 2) return;
    state.lines.push({ points: line.points, age: 0 });
    audio.splash();
  }

  function spawnBee(index) {
    const { w, h } = stage;
    const fromSide = index % 7 === 4;
    let x, y, vx, vy;
    if (fromSide) {
      const left = index % 2 === 0;
      x = left ? -18 : w + 18;
      y = rand(h * 0.2, h * 0.5);
      vx = (left ? 1 : -1) * rand(70, 120);
      vy = rand(-10, 40);
    } else {
      x = rand(w * 0.12, w * 0.88);
      y = -20;
      vx = rand(-35, 35);
      vy = rand(20, 60);
    }
    state.bees.push({
      x, y, vx, vy,
      r: clamp(Math.min(w, h) * 0.019, 9, 14),
      phase: rand(0, TAU),
      blocked: false,
      born: state.time,
    });
  }

  function burst(x, y, color, amount = 10, power = 150) {
    for (let i = 0; i < amount; i++) {
      const a = rand(0, TAU);
      const sp = rand(power * 0.2, power);
      state.particles.push({
        x, y,
        vx: Math.cos(a) * sp,
        vy: Math.sin(a) * sp,
        life: rand(0.3, 0.7),
        max: 0.7,
        size: rand(1.5, 4),
        color,
      });
    }
  }

  function hitDog(bee) {
    const d = dog();
    state.hearts--;
    state.dogFlash = 1;
    state.shake = 10;
    state.flash = 0.8;
    state.bubble = { text: state.hearts > 0 ? "OUCH!" : "NOOO!", life: 1.6 };
    burst(d.x, d.y - d.size * 0.2, "#ff5d6c", 24, 220);
    audio.hurt();
    api.vibrate?.([25, 30, 50]);
    if (state.hearts <= 0 && state.phase === "play") {
      state.phase = "lost";
      state.loseT = 0;
      setTimeout(() => {
        if (!state.ended) {
          state.ended = true;
          api.lose("The bees got the dog. The dog has filed a formal complaint.");
        }
      }, 1000);
    }
  }

  function collideLines(bee) {
    if (bee.y > stage.h + 30) return;
    for (const line of state.lines) {
      if (line.age > LINE_LIFE - 0.8) continue;
      const pts = line.points;
      for (let i = 0; i < pts.length - 1; i++) {
        const a = pts[i];
        const b = pts[i + 1];
        const abx = b.x - a.x;
        const aby = b.y - a.y;
        const len2 = abx * abx + aby * aby || 1;
        let t = ((bee.x - a.x) * abx + (bee.y - a.y) * aby) / len2;
        t = clamp(t, 0, 1);
        const px = a.x + abx * t;
        const py = a.y + aby * t;
        const dx = bee.x - px;
        const dy = bee.y - py;
        const dd = Math.hypot(dx, dy);
        const target = bee.r + LINE_WIDTH / 2;
        if (dd < target && dd > 0.001) {
          const nx = dx / dd;
          const ny = dy / dd;
          bee.x = px + nx * target;
          bee.y = py + ny * target;
          const vn = bee.vx * nx + bee.vy * ny;
          if (vn < 0) {
            bee.vx -= 1.55 * vn * nx;
            bee.vy -= 1.55 * vn * ny;
          }
          const tangent = (Math.random() - 0.5) * 90;
          bee.vx += -ny * tangent * 0.35;
          bee.vy += nx * tangent * 0.35;
          if (!bee.blocked) {
            bee.blocked = true;
            state.blocked++;
            state.tickle = 0.5;
          }
          if (state.time - (bee.lastSound || 0) > 0.18) {
            bee.lastSound = state.time;
            audio.tick();
          }
        }
      }
    }
  }

  function update(dt) {
    state.time += dt;
    state.shake = Math.max(0, state.shake - dt * 24);
    state.flash = Math.max(0, state.flash - dt * 2.6);
    state.dogFlash = Math.max(0, state.dogFlash - dt * 2.2);
    state.tickle = Math.max(0, state.tickle - dt);

    if (state.bubble.life > 0) state.bubble.life -= dt;

    if (state.phase === "play") {
      state.ink = Math.min(state.maxInk, state.ink + 38 * dt);
      while (state.spawnIndex < SPAWN_TIMES.length && state.time >= SPAWN_TIMES[state.spawnIndex]) {
        spawnBee(state.spawnIndex);
        state.spawnIndex++;
      }
      if (state.time >= DURATION) {
        state.phase = "won";
        state.winT = 0;
        if (!state.ended) {
          state.ended = true;
          audio.win();
          const stars = state.hearts >= 3 ? 3 : state.hearts >= 2 ? 2 : 1;
          setTimeout(() => {
            api.win(stars, state.hearts * 100 + state.blocked, {
              note: `${state.hearts} of 3 hearts left. ${state.blocked} bees bonked off your hand-drawn shields.`,
            });
          }, 700);
        }
      }
    } else if (state.phase === "won") {
      state.winT += dt;
    } else if (state.phase === "lost") {
      state.loseT += dt;
    }

    const d = dog();

    // lines age out in the sun
    for (const line of state.lines) line.age += dt;
    state.lines = state.lines.filter((line) => line.age < LINE_LIFE);

    for (const bee of state.bees) {
      bee.phase += dt;
      if (state.phase === "play" || state.phase === "lost") {
        bee.vy += 92 * dt;
        const seek = clamp((d.x - bee.x) * 0.55, -48, 48);
        bee.vx += seek * dt;
        bee.vx = clamp(bee.vx, -150, 150);
        bee.vy = clamp(bee.vy, -80, 290);
        bee.x += bee.vx * dt;
        bee.y += bee.vy * dt;

        if (bee.x < bee.r) { bee.x = bee.r; bee.vx = Math.abs(bee.vx) * 0.8; }
        if (bee.x > stage.w - bee.r) { bee.x = stage.w - bee.r; bee.vx = -Math.abs(bee.vx) * 0.8; }

        collideLines(bee);

        if (dist(bee.x, bee.y, d.x, d.y - d.radius * 0.15) < bee.r + d.radius && state.phase === "play") {
          bee.dead = true;
          hitDog(bee);
        }
      }
    }
    state.bees = state.bees.filter((b) => !b.dead && b.y < stage.h + 40);

    for (const p of state.particles) {
      p.life -= dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += 250 * dt;
      p.vx *= 1 - dt * 1.5;
    }
    state.particles = state.particles.filter((p) => p.life > 0);
  }

  function drawHeart(ctx, x, y, size, filled) {
    ctx.save();
    ctx.translate(x, y);
    ctx.beginPath();
    ctx.moveTo(0, size * 0.32);
    ctx.bezierCurveTo(-size * 0.62, -size * 0.18, -size * 0.34, -size * 0.58, 0, -size * 0.25);
    ctx.bezierCurveTo(size * 0.34, -size * 0.58, size * 0.62, -size * 0.18, 0, size * 0.32);
    ctx.closePath();
    if (filled) {
      ctx.fillStyle = "#ff5d6c";
      ctx.fill();
      ctx.strokeStyle = "#20142e";
      ctx.lineWidth = 2;
      ctx.stroke();
    } else {
      ctx.strokeStyle = "rgba(255,255,255,0.28)";
      ctx.lineWidth = 2;
      ctx.stroke();
    }
    ctx.restore();
  }

  function drawBackground(ctx, w, h) {
    const sky = ctx.createLinearGradient(0, 0, 0, h);
    sky.addColorStop(0, "#ffb36b");
    sky.addColorStop(0.35, "#ff8fa3");
    sky.addColorStop(0.7, "#9b4d8f");
    sky.addColorStop(1, "#4a2360");
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, w, h);

    // sun
    ctx.save();
    ctx.globalAlpha = 0.9;
    const sun = ctx.createRadialGradient(w * 0.74, h * 0.17, 4, w * 0.74, h * 0.17, w * 0.24);
    sun.addColorStop(0, "#fff6c9");
    sun.addColorStop(0.4, "#ffe27a");
    sun.addColorStop(1, "rgba(255, 210, 63, 0)");
    ctx.fillStyle = sun;
    ctx.beginPath();
    ctx.arc(w * 0.74, h * 0.17, w * 0.24, 0, TAU);
    ctx.fill();
    ctx.restore();

    // clouds
    drawSprite(ctx, "cloud", w * 0.18, h * 0.12, w * 0.3, { alpha: 0.65 });
    drawSprite(ctx, "cloud", w * 0.86, h * 0.25, w * 0.22, { alpha: 0.45 });
    drawSprite(ctx, "cloud", w * 0.4, h * 0.06, w * 0.18, { alpha: 0.35 });

    // hills
    const hill1 = ctx.createLinearGradient(0, h * 0.6, 0, h);
    hill1.addColorStop(0, "#4e8f68");
    hill1.addColorStop(1, "#2d5e48");
    ctx.fillStyle = hill1;
    ctx.beginPath();
    ctx.moveTo(0, h * 0.72);
    ctx.quadraticCurveTo(w * 0.25, h * 0.58, w * 0.52, h * 0.7);
    ctx.quadraticCurveTo(w * 0.8, h * 0.82, w, h * 0.64);
    ctx.lineTo(w, h);
    ctx.lineTo(0, h);
    ctx.closePath();
    ctx.fill();

    const hill2 = ctx.createLinearGradient(0, h * 0.75, 0, h);
    hill2.addColorStop(0, "#3f7d59");
    hill2.addColorStop(1, "#224b39");
    ctx.fillStyle = hill2;
    ctx.beginPath();
    ctx.moveTo(0, h * 0.85);
    ctx.quadraticCurveTo(w * 0.3, h * 0.76, w * 0.58, h * 0.86);
    ctx.quadraticCurveTo(w * 0.8, h * 0.93, w, h * 0.84);
    ctx.lineTo(w, h);
    ctx.lineTo(0, h);
    ctx.closePath();
    ctx.fill();

    // bushes and flowers
    drawSprite(ctx, "bush", w * 0.06, h * 0.78, w * 0.2, { alpha: 0.9 });
    drawSprite(ctx, "bush", w * 0.96, h * 0.84, w * 0.17, { alpha: 0.85 });
    for (let i = 0; i < 5; i++) {
      drawSprite(ctx, "flower", w * (0.12 + i * 0.19), h * (0.9 + (i % 2) * 0.035), w * 0.05, { alpha: 0.85 });
    }

    // sunbeam haze
    ctx.save();
    ctx.globalAlpha = 0.08;
    ctx.fillStyle = "#fff";
    ctx.beginPath();
    ctx.moveTo(w * 0.74, h * 0.17);
    ctx.lineTo(w * 0.4, h);
    ctx.lineTo(w * 0.58, h);
    ctx.lineTo(w * 0.82, h * 0.2);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function drawLines(ctx) {
    for (const line of state.lines) {
      const pts = line.points;
      const alpha = line.age > LINE_LIFE - 2 ? clamp((LINE_LIFE - line.age) / 2, 0, 1) : 1;
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.strokeStyle = "rgba(255, 196, 61, 0.26)";
      ctx.lineWidth = LINE_WIDTH + 8;
      ctx.beginPath();
      pts.forEach((p, i) => { i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y); });
      ctx.stroke();

      const grad = ctx.createLinearGradient(0, 0, 0, stage.h);
      grad.addColorStop(0, "#ffe89c");
      grad.addColorStop(0.5, "#ffc93f");
      grad.addColorStop(1, "#ff9f1a");
      ctx.strokeStyle = grad;
      ctx.lineWidth = LINE_WIDTH;
      ctx.beginPath();
      pts.forEach((p, i) => { i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y); });
      ctx.stroke();

      ctx.strokeStyle = "rgba(255,255,255,0.55)";
      ctx.lineWidth = 2.2;
      ctx.beginPath();
      pts.forEach((p, i) => { i ? ctx.lineTo(p.x, p.y - 1) : ctx.moveTo(p.x, p.y - 1); });
      ctx.stroke();
      ctx.restore();
    }

    if (state.drawing) {
      const pts = state.drawing.points;
      ctx.save();
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.strokeStyle = "rgba(255, 201, 63, 0.9)";
      ctx.lineWidth = LINE_WIDTH;
      ctx.beginPath();
      pts.forEach((p, i) => { i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y); });
      ctx.stroke();
      const end = pts[pts.length - 1];
      ctx.fillStyle = "#fff4c2";
      ctx.beginPath();
      ctx.arc(end.x, end.y, LINE_WIDTH * 0.55, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
  }

  function drawDog(ctx, w, h) {
    const d = dog();
    const bob = Math.sin(state.time * 2.4) * 2;
    const flash = state.dogFlash > 0 && Math.floor(state.time * 18) % 2 === 0;

    ctx.save();
    ctx.fillStyle = "rgba(20, 10, 30, 0.22)";
    ctx.beginPath();
    ctx.ellipse(d.x, d.y + d.size * 0.37, d.size * 0.3, d.size * 0.07, 0, 0, TAU);
    ctx.fill();

    if (state.phase === "won") {
      const t = Math.min(1, state.winT / 0.8);
      ctx.translate(d.x, d.y - easeOutCubic(t) * 32 + bob);
      ctx.scale(1 + Math.sin(state.winT * 8) * 0.03, 1 + Math.sin(state.winT * 8) * 0.03);
      drawSprite(ctx, "dog", 0, 0, d.size, { alpha: flash ? 0.55 : 1 });
    } else {
      drawSprite(ctx, "dog", d.x, d.y + bob, d.size, {
        alpha: flash ? 0.55 : 1,
        rot: state.dogFlash * 0.04 * Math.sin(state.time * 40),
      });
    }
    ctx.restore();

    // speech bubble
    if (state.bubble.life > 0) {
      const a = clamp(state.bubble.life, 0, 1);
      const text = state.bubble.text;
      ctx.save();
      ctx.globalAlpha = a;
      ctx.font = `900 ${Math.round(clamp(w * 0.042, 13, 18))}px ${DISPLAY}`;
      const tw = ctx.measureText(text).width;
      const bw = tw + 22;
      const bh = 30;
      const bx = clamp(d.x + d.size * 0.24, 10, w - bw - 10);
      const by = d.y - d.size * 0.72;
      ctx.fillStyle = "#fff8ee";
      ctx.strokeStyle = "#20142e";
      ctx.lineWidth = 2.5;
      roundRect(ctx, bx, by, bw, bh, 11);
      ctx.fill();
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(bx + 12, by + bh - 1);
      ctx.lineTo(bx + 4, by + bh + 10);
      ctx.lineTo(bx + 24, by + bh - 1);
      ctx.closePath();
      ctx.fillStyle = "#fff8ee";
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = "#20142e";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(text, bx + bw / 2, by + bh / 2 + 1);
      ctx.restore();
    }
  }

  function drawBees(ctx) {
    for (const bee of state.bees) {
      const flap = Math.sin(state.time * 28 + bee.phase);
      ctx.save();
      ctx.translate(bee.x, bee.y);
      ctx.rotate(clamp(bee.vx * 0.004, -0.3, 0.3) + Math.sin(state.time * 7 + bee.phase) * 0.08);
      ctx.globalAlpha = 0.18;
      ctx.fillStyle = "#20142e";
      ctx.beginPath();
      ctx.ellipse(0, bee.r + 8, bee.r * 0.75, 3, 0, 0, TAU);
      ctx.fill();
      ctx.globalAlpha = 1;
      drawSprite(ctx, "bee", 0, 0, bee.r * 2.9, { flipY: flap < 0 });
      ctx.restore();
    }
  }

  function drawHud(ctx, w, h) {
    const pad = 12;
    const top = 10;
    // hearts
    ctx.save();
    ctx.fillStyle = "rgba(20, 10, 30, 0.42)";
    roundRect(ctx, pad, top, 104, 32, 10);
    ctx.fill();
    for (let i = 0; i < 3; i++) {
      drawHeart(ctx, pad + 19 + i * 26, top + 16, 18, i < state.hearts);
    }
    ctx.restore();

    // timer
    ctx.save();
    const timeLeft = Math.max(0, DURATION - state.time);
    ctx.fillStyle = "rgba(20, 10, 30, 0.42)";
    roundRect(ctx, w - pad - 62, top, 62, 32, 10);
    ctx.fill();
    ctx.fillStyle = timeLeft < 5 ? "#ffd23f" : "#fff";
    ctx.font = `900 15px ${DISPLAY}`;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(`${timeLeft.toFixed(1)}s`, w - pad - 31, top + 17);
    ctx.restore();

    // ink bar
    const barW = clamp(w * 0.32, 100, 140);
    const barX = w / 2 - barW / 2;
    const barY = top + 12;
    ctx.save();
    ctx.fillStyle = "rgba(20, 10, 30, 0.42)";
    roundRect(ctx, barX - 8, top, barW + 16, 32, 10);
    ctx.fill();
    ctx.fillStyle = "rgba(255,255,255,0.14)";
    roundRect(ctx, barX, barY, barW, 8, 4);
    ctx.fill();
    const pct = state.ink / state.maxInk;
    const grad = ctx.createLinearGradient(barX, 0, barX + barW, 0);
    grad.addColorStop(0, "#ffe89c");
    grad.addColorStop(1, "#ff9f1a");
    ctx.fillStyle = grad;
    roundRect(ctx, barX, barY, Math.max(2, barW * pct), 8, 4);
    ctx.fill();
    ctx.fillStyle = "rgba(255,255,255,0.55)";
    ctx.font = `900 6.5px ${DISPLAY}`;
    ctx.textAlign = "center";
    ctx.fillText("HONEY INK", w / 2, top + 27);
    ctx.restore();
  }

  function draw() {
    const { ctx } = stage;
    const w = stage.w;
    const h = stage.h;
    ctx.save();
    if (state.shake > 0.1) ctx.translate(rand(-state.shake, state.shake), rand(-state.shake, state.shake));

    drawBackground(ctx, w, h);
    drawDog(ctx, w, h);
    drawBees(ctx);
    drawLines(ctx);

    for (const p of state.particles) {
      const a = clamp(p.life / p.max, 0, 1);
      ctx.globalAlpha = a;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * a + 0.4, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    drawHud(ctx, w, h);

    if (state.flash > 0) {
      ctx.fillStyle = `rgba(255, 93, 108, ${state.flash * 0.14})`;
      ctx.fillRect(0, 0, w, h);
    }

    if (state.phase === "lost") {
      ctx.save();
      ctx.fillStyle = "rgba(20, 10, 30, 0.42)";
      ctx.fillRect(0, 0, w, h);
      ctx.fillStyle = "#fff";
      ctx.font = `900 ${Math.round(clamp(w * 0.09, 28, 44))}px ${DISPLAY}`;
      ctx.textAlign = "center";
      ctx.fillText("THE BEES WIN", w / 2, h * 0.42);
      ctx.restore();
    }

    ctx.restore();
  }

  // immediate first bee so the scene reads instantly
  spawnBee(0);
  state.spawnIndex = 1;

  const loop = createLoop((dt) => {
    update(dt);
    draw();
  });

  return {
    destroy() {
      loop.stop();
      stopPointer();
      stage.destroy();
    },
  };
}

