function topCount(t){if(!t.length)return 0;const c=top(t);let n=1;while(n<t.length&&t[t.length-1-n]===c)n++;return n;}
function done(s){return s.every(t=>t.length===0||(t.length===CAP&&t.every(c=>c===t[0])));}
function moves(s){const out=[];for(let i=0;i<s.length;i++){if(!s[i].length)continue;const c=top(s[i]);for(let j=0;j<s.length;j++){if(i===j)continue;const d=s[j];if(d.length>=CAP)continue;if(d.length&&top(d)!==c)continue;const amt=Math.min(topCount(s[i]),CAP-d.length);const ns=s.map(t=>t.slice());for(let k=0;k<amt;k++){ns[i].pop();ns[j].push(c);}out.push({ns,move:[i,j,amt]});}}return out;}
